                obstacles.add(IsoObstacle(2, "COLUMN", 280f, 280f, 18f, themeColor, name = "Void Rift Obelisk"))
                obstacles.add(IsoObstacle(3, "CONSOLE", 200f, 190f, 20f, QuantumNeonPurple, name = "Reality Anchor Interface", interactable = true))
