            Biome.DESERT -> listOf(QuantumNeonOrange, Color.Yellow)
            Biome.SNOW -> listOf(QuantumNeonBlue, Color.Cyan)
            Biome.VOLCANIC -> listOf(QuantumNeonRed, QuantumNeonOrange)
            Biome.RUINS, Biome.VOID_SEA -> listOf(QuantumNeonPurple, QuantumNeonRed)
        }
        val enemyNames = when (selectedBiome) {
            Biome.GRASSLANDS -> listOf("Aurelian Drone", "Sentinel Mech")
            Biome.DESERT -> listOf("Scavenger Seeker", "Dune Resonator")
            Biome.SNOW -> listOf("Frostbite Hunter", "Cryo Crawler")
            Biome.VOLCANIC -> listOf("Magma Automaton", "Thermal Mech")
            Biome.RUINS, Biome.VOID_SEA -> listOf("Void Defiler", "Null Colossus Orb")
        }
        
        for (i in 0 until 4) {
            val ex = Random.nextFloat() * 220f + 90f
            val ey = Random.nextFloat() * 220f + 90f
            val maxHp = 100 + gameState.level * 40
            enemies.add(
                IsoEnemy(
                    id = i.toLong(),
                    name = enemyNames[i % enemyNames.size],
                    x = ex,
                    y = ey,
                    hp = maxHp,
                    maxHp = maxHp,
                    color = enemyColors[i % enemyColors.size],
                    state = "PATROL",
                    patrolTargetX = ex,
                    patrolTargetY = ey,
                    stateTimer = Random.nextInt(60, 120)
                )
            )
        }

        // Spawn 4 wildlife creatures matching biome
        val biomeWildlife = when (selectedBiome) {
            Biome.GRASSLANDS -> listOf(
                Triple("Leaf Hare", "🐇", "SKITTISH"),
                Triple("Moss Deer", "🦌", "SKITTISH"),
                Triple("Glow Squirrel", "🐿️", "CURIOUS"),
                Triple("Briar Boar", "🐗", "NEUTRAL")
            )
            Biome.SNOW -> listOf(
                Triple("Snow Hare", "🐇", "SKITTISH"),
                Triple("Ice Fox", "🦊", "CURIOUS"),
                Triple("Frost Ram", "🐏", "NEUTRAL"),
                Triple("Glacial Wolf", "🐺", "TERRITORIAL")
            )
            Biome.DESERT -> listOf(
                Triple("Sand Skink", "🦎", "PASSIVE"),
                Triple("Dune Beetle", "🪲", "PASSIVE"),
                Triple("Scorch Runner", "🦂", "TERRITORIAL"),
                Triple("Needle Porcupine", "🦔", "NEUTRAL")
            )
            Biome.VOLCANIC -> listOf(
                Triple("Stone Goat", "🐐", "NEUTRAL"),
                Triple("Boulder Bear", "🐻", "NEUTRAL"),
                Triple("Cliff Hawk", "🦅", "TERRITORIAL"),
                Triple("Mushroom Golem", "🍄", "NEUTRAL")
            )
            Biome.RUINS, Biome.VOID_SEA -> listOf(
                Triple("Lumen Slime", "🧼", "CURIOUS"),
                Triple("Crystal Spider", "🕷️", "TERRITORIAL"),
                Triple("Ancient Probe", "🛸", "CURIOUS"),
                Triple("Crystal Golem", "💎", "TERRITORIAL")
            )
        }

        for (i in 0 until 4) {
            val wx = Random.nextFloat() * 240f + 80f
            val wy = Random.nextFloat() * 240f + 80f
            val template = biomeWildlife[i % biomeWildlife.size]
            val rarity = when (i) {
                0 -> "Common"
                1 -> "Common"
                2 -> "Rare"
                else -> "Epic"
            }
            val drops = when (template.first) {
                "Leaf Hare", "Snow Hare" -> listOf("Meat", "Hide", "Herb")
                "Moss Deer", "Frost Ram" -> listOf("Meat", "Hide", "Bone")
                "Glow Squirrel", "Ice Fox" -> listOf("Hide", "Bone")
                "Briar Boar", "Boulder Bear" -> listOf("Meat", "Bone", "Hide")
                "Dune Beetle", "Sand Skink" -> listOf("Shell", "Hide")
                "Scorch Runner", "Crystal Spider" -> listOf("Bone", "Venom", "Crystal")
                "Needle Porcupine" -> listOf("Hide", "Needle")
                "Stone Goat" -> listOf("Meat", "Hide")
                "Cliff Hawk" -> listOf("Feather", "Meat")
                "Mushroom Golem" -> listOf("Mushroom Essence", "Herb")
                "Lumen Slime" -> listOf("Slime Ball", "Glow Essence")
                "Ancient Probe" -> listOf("Core", "Scrap Metal")
                "Crystal Golem" -> listOf("Rare Gem", "Crystal")
                else -> listOf("Biomass")
            }
            wildlifeList.add(
                IsoWildlife(
                    id = System.nanoTime() + i,
                    name = template.first,
                    category = when (selectedBiome) {
                        Biome.GRASSLANDS -> "Forest & Grassland"
                        Biome.SNOW -> "Arctic"
                        Biome.DESERT -> "Desert"
                        Biome.VOLCANIC -> "Mountain & Volcanic"
                        else -> "Cavern & Mineral"
                    },
                    x = wx,
                    y = wy,
                    emoji = template.second,
                    color = when (template.third) {
                        "SKITTISH" -> QuantumNeonGreen
                        "CURIOUS" -> QuantumNeonBlue
                        "TERRITORIAL" -> QuantumNeonRed
                        "NEUTRAL" -> QuantumNeonOrange
                        else -> Color.Gray
                    },
                    behavior = template.third,
                    rarity = rarity,
                    drops = drops,
                    speed = when (template.third) {
                        "SKITTISH" -> 35f
                        "CURIOUS" -> 25f
                        "TERRITORIAL" -> 40f
                        else -> 20f
                    }
                )
            )
        }
        
        // Spawn 6 collectibles
        val mats = when (selectedBiome) {
            Biome.GRASSLANDS -> listOf("Scrap Metal" to "⚡", "Credits" to "💎")
            Biome.DESERT -> listOf("Alloy Plate" to "⚙️", "Credits" to "💎")
            Biome.SNOW -> listOf("Nano Fiber" to "🧶", "Credits" to "💎")
            Biome.VOLCANIC -> listOf("Lava Core" to "🔥", "Credits" to "💎")
            Biome.RUINS, Biome.VOID_SEA -> listOf("Voidium" to "🔮", "Singularium" to "🌀")
        }
        for (i in 0 until 6) {
            val cx = Random.nextFloat() * 280f + 60f
            val cy = Random.nextFloat() * 280f + 60f
            val m = mats[Random.nextInt(mats.size)]
            collectibles.add(
                IsoCollectible(
                    id = i.toLong(),
                    type = if (m.second == "💎") "Credits" else m.first,
                    x = cx,
                    y = cy,
                    amount = Random.nextInt(20, 60),
                    symbol = m.second
                )
            )
        }
        
        // Load persistent custom structures for the current biome
        gameState.deployedStructures.filter { it.biomeName == selectedBiome.name }.forEach { ds ->
            obstacles.add(
                IsoObstacle(
                    id = ds.id,
                    type = ds.type,
                    x = ds.x,
                    y = ds.y,
                    radius = if (ds.type.startsWith("BUILDING")) 35f else if (ds.type.startsWith("PROP_")) 20f else if (ds.type.startsWith("NPC_")) 15f else 45f,
                    color = Color(ds.colorVal.toULong()),
                    name = ds.name,
                    interactable = true,
                    interactedText = if (ds.type.startsWith("PROP_")) "Accessing interactive tactical prop module..." else if (ds.type.startsWith("NPC_")) "Interacted with custom humanoid sector operative: ${ds.name}." else if (ds.type == "INTERNAL_MODULE") "Successfully loaded modular room network. Faction: ${ds.factionName}." else "Scanning active core modular network... Code: SECURE.",
                    hp = if (ds.type.startsWith("PROP_")) 300 else if (ds.type.startsWith("NPC_")) 150 else if (ds.type.startsWith("BUILDING")) 500 else 800,
                    maxHp = if (ds.type.startsWith("PROP_")) 300 else if (ds.type.startsWith("NPC_")) 150 else if (ds.type.startsWith("BUILDING")) 500 else 800
                )
            )
        }
    }
    
    // Sandbox physics game loop (60 FPS)
    if (activeMode == 0) {
        LaunchedEffect(selectedBiome) {
            var lastTime = System.currentTimeMillis()
            while (true) {
                val now = System.currentTimeMillis()
                val delta = (now - lastTime) / 1000f
                lastTime = now
                ticks++
                
                // 1. Move Player
                var speed = 110f
                if (dashActiveTime > 0) {
                    speed = 280f
                    dashActiveTime--
                }
                if (shieldActiveTime > 0) {
                    shieldActiveTime--
                }
                
                // Input drives velocity directly; once it is released the vector
                // decays exponentially so the sprite eases to a halt (blueprint 3A).
                playerVelocity = if (joystickX != 0f || joystickY != 0f) {
                    Vec2(joystickX, joystickY)
                } else {
                    IsometricMath.applyFriction(playerVelocity, delta)
                }

                if (playerVelocity != Vec2.ZERO) {
                    val moveX = playerVelocity.x
                    val moveY = playerVelocity.y
                    val testX = (playerX + moveX * speed * delta).coerceIn(30f, 370f)
                    val testY = (playerY + moveY * speed * delta).coerceIn(30f, 370f)

                    var collides = false
                    for (obs in obstacles) {
                        if (!obs.isDestroyed) {
                            val dx = testX - obs.x
                            val dy = testY - obs.y
                            if (sqrt(dx * dx + dy * dy) < obs.radius) {
                                collides = true
                                break
                            }
                        }
                    }
                    
                    if (!collides) {
                        playerX = testX
                        playerY = testY
                    } else {
                        // Sliding collision helper: try X-only
                        var collidesX = false
                        val testXOnly = (playerX + moveX * speed * delta).coerceIn(30f, 370f)
                        for (obs in obstacles) {
                            if (!obs.isDestroyed) {
                                val dx = testXOnly - obs.x
                                val dy = playerY - obs.y
                                if (sqrt(dx * dx + dy * dy) < obs.radius) {
                                    collidesX = true
                                    break
                                }
                            }
                        }
                        if (!collidesX) {
                            playerX = testXOnly
                        } else {
                            // Try Y-only
                            var collidesY = false
                            val testYOnly = (playerY + moveY * speed * delta).coerceIn(30f, 370f)
                            for (obs in obstacles) {
                                if (!obs.isDestroyed) {
                                    val dx = playerX - obs.x
                                    val dy = testYOnly - obs.y
                                    if (sqrt(dx * dx + dy * dy) < obs.radius) {
                                        collidesY = true
                                        break
                                    }
                                }
                            }
                            if (!collidesY) {
                                playerY = testYOnly
                            }
                        }
                    }
                    
                    val len = sqrt(moveX * moveX + moveY * moveY)
                    if (len > 0.05f) {
                        playerDirX = moveX / len
                        playerDirY = moveY / len
                    }
                    IsometricMath.snapToOctant(moveX, moveY)?.let { playerFacing = it }
                }
                
                // 2. Slashing sword swing timer
                if (isAttacking) {
                    attackFrame++
                    if (attackFrame > 6) {
                        isAttacking = false
                        attackFrame = 0
                    }
                }
                
                // 3. Projectile & particle updates
                val pIter = particles.iterator()
                while (pIter.hasNext()) {
                    val p = pIter.next()
                    p.x += p.vx * delta
                    p.y += p.vy * delta
                    p.alpha -= 1.8f * delta
                    p.life--
                    
                    if (p.life <= 0 || p.alpha <= 0f) {
                        pIter.remove()
                    } else if (p.isPlayerProjectile) {
                        var hitSomething = false
                        
                        // 1. Check hitting enemies
                        val eIter = enemies.iterator()
                        while (eIter.hasNext()) {
                            val enemy = eIter.next()
                            val edx = enemy.x - p.x
                            val edy = enemy.y - p.y
                            val edist = sqrt(edx * edx + edy * edy)
                            if (edist < 22f) {
                                hitSomething = true
                                enemy.hitCooldown = 12
                                enemy.state = "HIT"
                                
                                val damage = ((gameState.currentWeapon.baseAtk + gameState.totalAtkBonus) * (1f + gameState.level * 0.12f)).toInt() + Random.nextInt(-6, 8)
                                enemy.hp = (enemy.hp - damage).coerceAtLeast(0)
                                
                                damageNumbers.add(
                                    IsoDamageNumber(
                                        id = System.nanoTime(),
                                        text = "🎯 $damage",
                                        x = enemy.x,
                                        y = enemy.y - 12f,
                                        color = p.color
                                    )
                                )
                                
                                // Splash particles on hit
                                for (k in 0..5) {
                                    particles.add(
                                        IsoParticle(
                                            x = enemy.x,
                                            y = enemy.y,
                                            vx = Random.nextFloat() * 120f - 60f,
                                            vy = Random.nextFloat() * 120f - 60f,
                                            color = p.color,
                                            size = 4f,
                                            life = 10
                                        )
                                    )
                                }
                                
                                if (enemy.hp <= 0) {
                                    eIter.remove()
                                    handleEnemyDefeat(enemy)
                                }
                                break
                            }
                        }
                        
                        if (!hitSomething) {
                            // 2. Check hitting destructible obstacles
                            for (obs in obstacles) {
                                if (obs.isDestructible && !obs.isDestroyed) {
                                    val odx = obs.x - p.x
                                    val ody = obs.y - p.y
                                    val odist = sqrt(odx * odx + ody * ody)
                                    if (odist < 22f) {
                                        hitSomething = true
                                        val damage = ((gameState.currentWeapon.baseAtk + gameState.totalAtkBonus) * (1f + gameState.level * 0.12f)).toInt() + Random.nextInt(-4, 6)
                                        obs.hp = (obs.hp - damage).coerceAtLeast(0)
                                        
                                        // spark hit particles
                                        for (k in 0..4) {
                                            particles.add(
                                                IsoParticle(p.x, p.y, Random.nextFloat() * 80f - 40f, Random.nextFloat() * 80f - 40f, obs.color, 4f, 1f, 10)
                                            )
                                        }
                                        
                                        damageNumbers.add(IsoDamageNumber(System.nanoTime(), "💥 $damage", obs.x, obs.y - 12f, obs.color))
                                        
                                        if (obs.hp <= 0) {
                                            handleCrateDestruction(obs)
                                        }
                                        break
                                    }
                                }
                            }
                        }
                        
                        if (!hitSomething) {
                            // 3. Check hitting wildlife
                            val wIter = wildlifeList.iterator()
                            while (wIter.hasNext()) {
                                val wildlife = wIter.next()
                                val wdx = wildlife.x - p.x
                                val wdy = wildlife.y - p.y
                                val wdist = sqrt(wdx * wdx + wdy * wdy)
                                if (wdist < 22f) {
                                    hitSomething = true
                                    wildlife.hitCooldown = 15
                                    
                                    val dropItem = wildlife.drops.randomOrNull() ?: "Biomass"
                                    val creditReward = when (wildlife.rarity) {
                                        "Common" -> Random.nextInt(40, 85)
                                        "Rare" -> Random.nextInt(90, 160)
                                        "Epic" -> Random.nextInt(200, 350)
                                        else -> Random.nextInt(400, 800)
                                    }
                                    val xpReward = when (wildlife.rarity) {
                                        "Common" -> 50
                                        "Rare" -> 120
                                        "Epic" -> 250
                                        else -> 500
                                    }
                                    
                                    for (k in 0..6) {
                                        particles.add(IsoParticle(wildlife.x, wildlife.y, Random.nextFloat() * 100f - 50f, Random.nextFloat() * 100f - 50f, wildlife.color, 5f, 1f, 12))
                                    }
                                    
                                    damageNumbers.add(IsoDamageNumber(System.nanoTime(), "💥 Harvest: $dropItem", wildlife.x, wildlife.y - 12f, QuantumNeonGreen))
                                    damageNumbers.add(IsoDamageNumber(System.nanoTime() + 1, "+$creditReward Credits", wildlife.x, wildlife.y - 28f, QuantumNeonOrange))
                                    damageNumbers.add(IsoDamageNumber(System.nanoTime() + 2, "+$xpReward XP", playerX, playerY - 30f, QuantumNeonBlue))
                                    
                                    collectibles.add(
                                        IsoCollectible(
                                            id = System.nanoTime() + 3,
                                            type = dropItem,
                                            x = wildlife.x,
                                            y = wildlife.y,
                                            amount = when (wildlife.rarity) {
                                                "Common" -> Random.nextInt(1, 3)
                                                "Rare" -> Random.nextInt(3, 6)
                                                "Epic" -> Random.nextInt(5, 10)
                                                else -> Random.nextInt(10, 20)
                                            },
                                            symbol = "📦"
                                        )
                                    )
                                    
                                    viewModel.addResources(creditReward, xpReward / 4, xpReward)
                                    wIter.remove()
                                    break
                                }
                            }
                        }
                        
                        if (hitSomething) {
                            pIter.remove()
                        }
                    } else if (p.color == QuantumNeonRed) { // Enemy hostile projectle
                        val dx = playerX - p.x
                        val dy = playerY - p.y
                        val dist = sqrt(dx * dx + dy * dy)
                        if (dist < 18f) {
                            pIter.remove()
                            if (dashActiveTime > 0) {
                                damageNumbers.add(
                                    IsoDamageNumber(
                                        id = System.nanoTime(),
                                        text = "DODGED",
                                        x = playerX,
                                        y = playerY - 10f,
                                        color = QuantumNeonBlue
                                    )
                                )
                            } else if (shieldActiveTime > 0) {
                                damageNumbers.add(
                                    IsoDamageNumber(
                                        id = System.nanoTime(),
                                        text = "BLOCKED",
                                        x = playerX,
                                        y = playerY - 10f,
                                        color = QuantumNeonGreen
                                    )
                                )
                            } else {
                                val damageVal = Random.nextInt(15, 30)
                                localPlayerHp = (localPlayerHp - damageVal).coerceAtLeast(0)
                                viewModel.updatePlayerHealth(localPlayerHp)
                                damageNumbers.add(
                                    IsoDamageNumber(
                                        id = System.nanoTime(),
                                        text = "-$damageVal HP",
                                        x = playerX,
                                        y = playerY - 10f,
                                        color = QuantumNeonRed
                                    )
                                )
                                // Spark hit particles
                                for (k in 0..4) {
                                    particles.add(
                                        IsoParticle(
                                            x = playerX,
                                            y = playerY,
                                            vx = Random.nextFloat() * 100f - 50f,
                                            vy = Random.nextFloat() * 100f - 50f,
                                            color = QuantumNeonRed,
                                            size = 6f,
                                            life = 12
                                        )
                                    )
                                }
                                
                                if (localPlayerHp == 0) {
                                    // Respawn reboot
                                    localPlayerHp = gameState.maxHealth
                                    viewModel.updatePlayerHealth(localPlayerHp)
                                    playerX = 200f
                                    playerY = 200f
                                    damageNumbers.add(
                                        IsoDamageNumber(
                                            id = System.nanoTime(),
                                            text = "REBOOT",
                                            x = 200f,
                                            y = 200f,
                                            color = QuantumNeonPurple
                                        )
                                    )
                                }
                            }
                        }
                    }
                }
                
                // 4. Floating texts
                val dIter = damageNumbers.iterator()
                while (dIter.hasNext()) {
                    val d = dIter.next()
                    d.y -= 30f * delta
                    d.alpha -= 1.6f * delta
                    d.life--
                    if (d.life <= 0 || d.alpha <= 0f) {
                        dIter.remove()
                    }
                }
                
                // 5. Magnetize ground crystals
                collectibles.forEach { item ->
                    val dx = playerX - item.x
                    val dy = playerY - item.y
                    val dist = sqrt(dx * dx + dy * dy)
                    if (dist < 60f) {
                        item.isMagnetized = true
                    }
                    if (item.isMagnetized) {
                        item.x += (dx / dist) * 200f * delta
                        item.y += (dy / dist) * 200f * delta
                    }
                }
                
                val cIter = collectibles.iterator()
                while (cIter.hasNext()) {
                    val item = cIter.next()
                    val dx = playerX - item.x
                    val dy = playerY - item.y
                    if (sqrt(dx * dx + dy * dy) < 14f) {
                        cIter.remove()
                        
                        val credGain = if (item.type == "Credits") item.amount else 0
                        val naniteGain = if (item.type == "Nanites") item.amount else 0
                        
                        if (credGain > 0 || naniteGain > 0) {
                            viewModel.addResources(credGain, naniteGain, 10)
                        } else {
                            val category = when (item.type) {
                                "Scrap Metal", "Alloy Plate" -> "Scrap"
                                "Lava Core", "Voidium", "Singularium", "Crystal", "Rare Gem" -> "Mineral"
                                "Meat" -> "Food"
                                "Herb", "Venom", "Mushroom Essence", "Glow Essence" -> "Medicine"
                                "Hide", "Bone", "Shell", "Needle", "Feather", "Biomass", "Nano Fiber" -> "Crafting Material"
                                else -> "Crafting Material"
                            }
                            viewModel.addItemToInventory(
                                item.type,
                                category,
                                item.symbol,
                                item.amount,
                                "Salvaged $category: ${item.type} harvested from the wild."
                            )
                        }
                        
                        damageNumbers.add(
                            IsoDamageNumber(
                                id = System.nanoTime(),
                                text = "+${item.amount} ${item.type}",
                                x = playerX,
                                y = playerY - 15f,
                                color = QuantumNeonGreen
                            )
                        )
                        
                        for (k in 0..3) {
                            particles.add(
                                IsoParticle(
                                    x = playerX,
                                    y = playerY,
                                    vx = Random.nextFloat() * 80f - 40f,
                                    vy = Random.nextFloat() * 80f - 40f,
                                    color = QuantumNeonBlue,
                                    size = 5f,
                                    life = 15
                                )
                            )
                        }
                    }
                }
                
                // 6. Roaming Hostile AI
                enemies.forEach { enemy ->
                    if (enemy.hitCooldown > 0) enemy.hitCooldown--
                    if (enemy.shootCooldown > 0) enemy.shootCooldown--
                    
                    val dx = playerX - enemy.x
                    val dy = playerY - enemy.y
                    val dist = sqrt(dx * dx + dy * dy)
                    
                    if (dist < 110f && shieldActiveTime == 0) {
                        enemy.state = "CHASE"
                        val speedChase = 45f
                        val testEX = enemy.x + (dx / dist) * speedChase * delta
                        val testEY = enemy.y + (dy / dist) * speedChase * delta
                        var eCollides = false
                        for (obs in obstacles) {
                            if (!obs.isDestroyed) {
                                val odx = testEX - obs.x
                                val ody = testEY - obs.y
                                if (sqrt(odx * odx + ody * ody) < obs.radius + 8f) {
                                    eCollides = true
                                    break
                                }
                            }
                        }
                        if (!eCollides) {
                            enemy.x = testEX
                            enemy.y = testEY
                        }
                        
                        if (enemy.shootCooldown <= 0) {
                            enemy.shootCooldown = 65
                            particles.add(
                                IsoParticle(
                                    x = enemy.x,
                                    y = enemy.y,
                                    vx = (dx / dist) * 160f,
                                    vy = (dy / dist) * 160f,
                                    color = QuantumNeonRed,
                                    size = 12f,
                                    life = 40
                                )
                            )
                        }
                    } else {
                        enemy.state = "PATROL"
                        enemy.stateTimer--
                        if (enemy.stateTimer <= 0) {
                            enemy.stateTimer = Random.nextInt(60, 150)
                            enemy.patrolTargetX = (enemy.x + Random.nextInt(-70, 70)).coerceIn(50f, 350f)
                            enemy.patrolTargetY = (enemy.y + Random.nextInt(-70, 70)).coerceIn(50f, 350f)
                        }
                        val tdx = enemy.patrolTargetX - enemy.x
                        val tdy = enemy.patrolTargetY - enemy.y
                        val tdist = sqrt(tdx * tdx + tdy * tdy)
                        if (tdist > 3f) {
                            val speedPatrol = 30f
                            val testEX = enemy.x + (tdx / tdist) * speedPatrol * delta
                            val testEY = enemy.y + (tdy / tdist) * speedPatrol * delta
                            var eCollides = false
                            for (obs in obstacles) {
                                if (!obs.isDestroyed) {
                                    val odx = testEX - obs.x
                                    val ody = testEY - obs.y
                                    if (sqrt(odx * odx + ody * ody) < obs.radius + 8f) {
                                        eCollides = true
                                        break
                                    }
                                }
                            }
                            if (!eCollides) {
                                enemy.x = testEX
                                enemy.y = testEY
                            }
                        }
                    }
                }
                
                // 7. Roaming Wildlife AI (Interactive Ambient Ecosystem)
                wildlifeList.forEach { wildlife ->
                    if (wildlife.hitCooldown > 0) wildlife.hitCooldown--
                    
                    val dx = playerX - wildlife.x
                    val dy = playerY - wildlife.y
                    val dist = sqrt(dx * dx + dy * dy)
                    
                    when (wildlife.behavior) {
                        "SKITTISH" -> {
                            if (dist < 75f) {
                                wildlife.state = "FLEE"
                                val moveSpeed = 70f
                                val testWX = wildlife.x - (dx / dist) * moveSpeed * delta
                                val testWY = wildlife.y - (dy / dist) * moveSpeed * delta
                                var wCollides = false
                                for (obs in obstacles) {
                                    if (!obs.isDestroyed) {
                                        val odx = testWX - obs.x
                                        val ody = testWY - obs.y
                                        if (sqrt(odx * odx + ody * ody) < obs.radius + 8f) {
                                            wCollides = true
                                            break
                                        }
                                    }
                                }
                                if (!wCollides) {
                                    wildlife.x = testWX.coerceIn(30f, 370f)
                                    wildlife.y = testWY.coerceIn(30f, 370f)
                                }
                                if (ticks % 20 == 0) {
                                    // Spawn small panic sweat particles
                                    particles.add(
                                        IsoParticle(
                                            x = wildlife.x,
                                            y = wildlife.y - 12f,
                                            vx = Random.nextFloat() * 20f - 10f,
                                            vy = -30f - Random.nextFloat() * 20f,
                                            color = QuantumNeonBlue,
                                            size = 4f,
                                            life = 15
                                        )
                                    )
                                }
                            } else {
                                wildlife.state = "WANDER"
                            }
                        }
                        "CURIOUS" -> {
                            if (dist < 90f && dist > 35f) {
                                wildlife.state = "APPROACH"
                                val moveSpeed = 35f
                                val testWX = wildlife.x + (dx / dist) * moveSpeed * delta
                                val testWY = wildlife.y + (dy / dist) * moveSpeed * delta
                                var wCollides = false
                                for (obs in obstacles) {
                                    if (!obs.isDestroyed) {
                                        val odx = testWX - obs.x
                                        val ody = testWY - obs.y
                                        if (sqrt(odx * odx + ody * ody) < obs.radius + 8f) {
                                            wCollides = true
                                            break
                                        }
                                    }
                                }
                                if (!wCollides) {
                                    wildlife.x = testWX.coerceIn(30f, 370f)
                                    wildlife.y = testWY.coerceIn(30f, 370f)
                                }
                                if (ticks % 30 == 0) {
                                    // Spawn curious sparkle particle
                                    particles.add(
                                        IsoParticle(
                                            x = wildlife.x + Random.nextFloat() * 10f - 5f,
                                            y = wildlife.y - 10f,
                                            vx = Random.nextFloat() * 10f - 5f,
                                            vy = -20f,
                                            color = QuantumNeonOrange,
                                            size = 5f,
                                            life = 12
                                        )
                                    )
                                }
                            } else if (dist <= 35f) {
                                wildlife.state = "IDLE"
                            } else {
                                wildlife.state = "WANDER"
                            }
                        }
                        "TERRITORIAL" -> {
                            if (dist < 65f) {
                                wildlife.state = "CHASE"
                                val moveSpeed = 48f
                                val testWX = wildlife.x + (dx / dist) * moveSpeed * delta
                                val testWY = wildlife.y + (dy / dist) * moveSpeed * delta
                                var wCollides = false
                                for (obs in obstacles) {
                                    if (!obs.isDestroyed) {
                                        val odx = testWX - obs.x
                                        val ody = testWY - obs.y
                                        if (sqrt(odx * odx + ody * ody) < obs.radius + 8f) {
                                            wCollides = true
                                            break
                                        }
                                    }
                                }
                                if (!wCollides) {
                                    wildlife.x = testWX.coerceIn(30f, 370f)
                                    wildlife.y = testWY.coerceIn(30f, 370f)
                                }
                                if (dist < 18f && ticks % 40 == 0) {
                                    if (dashActiveTime > 0) {
                                        damageNumbers.add(
                                            IsoDamageNumber(
                                                id = System.nanoTime(),
                                                text = "DODGED",
                                                x = playerX,
                                                y = playerY - 10f,
                                                color = QuantumNeonBlue
                                            )
                                        )
                                    } else if (shieldActiveTime > 0) {
                                        damageNumbers.add(
                                            IsoDamageNumber(
                                                id = System.nanoTime(),
                                                text = "BLOCKED",
                                                x = playerX,
                                                y = playerY - 10f,
                                                color = QuantumNeonGreen
                                            )
                                        )
                                    } else {
                                        // Attacks the player!
                                        val dmg = Random.nextInt(4, 9)
                                        localPlayerHp = (localPlayerHp - dmg).coerceAtLeast(0)
                                        viewModel.updatePlayerHealth(localPlayerHp)
                                        damageNumbers.add(
                                            IsoDamageNumber(
                                                id = System.nanoTime(),
                                                text = "-$dmg HP",
                                                x = playerX,
                                                y = playerY - 10f,
                                                color = QuantumNeonRed
                                            )
                                        )
                                        // red burst particles
                                        for (k in 0..3) {
                                            particles.add(
                                                IsoParticle(
                                                    x = playerX,
                                                    y = playerY,
                                                    vx = Random.nextFloat() * 60f - 30f,
                                                    vy = Random.nextFloat() * 60f - 30f,
                                                    color = QuantumNeonRed,
                                                    size = 6f,
                                                    life = 10
                                                )
                                            )
                                        }
                                        
                                        if (localPlayerHp == 0) {
                                            localPlayerHp = gameState.maxHealth
                                            viewModel.updatePlayerHealth(localPlayerHp)
                                            playerX = 200f
                                            playerY = 200f
                                            damageNumbers.add(
                                                IsoDamageNumber(
                                                    id = System.nanoTime(),
                                                    text = "REBOOT",
                                                    x = 200f,
                                                    y = 200f,
                                                    color = QuantumNeonPurple
                                                )
                                            )
                                        }
                                    }
                                }
                            } else {
                                wildlife.state = "WANDER"
                            }
                        }
                        else -> { // PASSIVE / NEUTRAL
                            wildlife.state = "WANDER"
                        }
                    }
                    
                    if (wildlife.state == "WANDER") {
                        wildlife.stateTimer--
                        if (wildlife.stateTimer <= 0) {
                            wildlife.stateTimer = Random.nextInt(60, 150)
                            wildlife.targetX = (wildlife.x + Random.nextInt(-60, 60)).coerceIn(50f, 350f)
                            wildlife.targetY = (wildlife.y + Random.nextInt(-60, 60)).coerceIn(50f, 350f)
                        }
                        val tdx = wildlife.targetX - wildlife.x
                        val tdy = wildlife.targetY - wildlife.y
                        val tdist = sqrt(tdx * tdx + tdy * tdy)
                        if (tdist > 3f) {
                            val speedWander = 18f
                            val testWX = wildlife.x + (tdx / tdist) * speedWander * delta
                            val testWY = wildlife.y + (tdy / tdist) * speedWander * delta
                            var wCollides = false
                            for (obs in obstacles) {
                                if (!obs.isDestroyed) {
                                    val odx = testWX - obs.x
                                    val ody = testWY - obs.y
                                    if (sqrt(odx * odx + ody * ody) < obs.radius + 8f) {
                                        wCollides = true
                                        break
                                    }
                                }
                            }
                            if (!wCollides) {
                                wildlife.x = testWX.coerceIn(30f, 370f)
                                wildlife.y = testWY.coerceIn(30f, 370f)
                            }
                        }
                    }
                }

                // 8. Custom Deployed Props & NPCs Real-time Kotlin Behaviors (Converted from Godot GDScript templates)
                obstacles.forEach { obs ->
                    if (!obs.isDestroyed) {
                        if (obs.type.startsWith("PROP_")) {
                            when (obs.type) {
                                "PROP_COOLING_CORE" -> {
                                    if (ticks % 35 == 0) {
                                        particles.add(
                                            IsoParticle(
                                                x = obs.x + Random.nextFloat() * 10f - 5f,
                                                y = obs.y - 15f,
                                                vx = Random.nextFloat() * 16f - 8f,
                                                vy = -20f - Random.nextFloat() * 15f,
                                                color = obs.color,
                                                size = 3.5f,
                                                life = 20
                                            )
                                        )
                                    }
                                    val dx = playerX - obs.x
                                    val dy = playerY - obs.y
                                    val dist = sqrt(dx * dx + dy * dy)
                                    if (dist < 40f && ticks % 60 == 0 && localPlayerHp < gameState.maxHealth) {
                                        localPlayerHp = (localPlayerHp + 2).coerceAtMost(gameState.maxHealth)
                                        viewModel.updatePlayerHealth(localPlayerHp)
                                        particles.add(IsoParticle(playerX, playerY - 10f, 0f, -25f, QuantumNeonGreen, 4f, 1f, 15))
                                    }
                                }
                                "PROP_TELEMETRY_DISH" -> {
                                    if (ticks % 60 == 0) {
                                        for (i in 0..7) {
                                            val angle = i * (6.28318f / 8f)
                                            particles.add(
                                                IsoParticle(
                                                    x = obs.x,
                                                    y = obs.y - 20f,
                                                    vx = cos(angle) * 40f,
                                                    vy = sin(angle) * 20f,
                                                    color = obs.color.copy(alpha = 0.8f),
                                                    size = 3f,
                                                    life = 30
                                                )
                                            )
                                        }
                                    }
                                }
                                "PROP_WAYFINDER" -> {
                                    if (ticks % 25 == 0) {
                                        particles.add(
                                            IsoParticle(
                                                x = obs.x,
                                                y = obs.y - 32f,
                                                vx = 0f,
                                                vy = -35f,
                                                color = obs.color,
                                                size = 4f,
                                                life = 15
                                            )
                                        )
                                    }
                                }
                                "PROP_VOID_OBELISK" -> {
                                    if (ticks % 50 == 0) {
                                        enemies.forEach { enemy ->
                                            if (enemy.hp > 0) {
                                                val edx = obs.x - enemy.x
                                                val edy = obs.y - enemy.y
                                                val edist = sqrt(edx * edx + edy * edy)
                                                if (edist < 110f) {
                                                    enemy.x += (edx / edist) * 15f
                                                    enemy.y += (edy / edist) * 15f
                                                    val dmg = 6
                                                    enemy.hp = (enemy.hp - dmg).coerceAtLeast(0)
                                                    
                                                    damageNumbers.add(
                                                        IsoDamageNumber(
                                                            id = System.nanoTime() + enemy.id,
                                                            text = "-$dmg Void",
                                                            x = enemy.x,
                                                            y = enemy.y - 12f,
                                                            color = obs.color
                                                        )
                                                    )
                                                    
                                                    for (step in 0..6) {
                                                        val t = step / 6f
                                                        particles.add(
                                                            IsoParticle(
                                                                x = obs.x * (1f - t) + enemy.x * t,
                                                                y = (obs.y - 45f) * (1f - t) + enemy.y * t,
                                                                vx = 0f,
                                                                vy = 0f,
                                                                color = obs.color,
                                                                size = 4f,
                                                                life = 6
                                                            )
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                "PROP_VOLATILE_DRUM" -> {
                                    if (ticks % 15 == 0) {
                                        enemies.forEach { enemy ->
                                            if (enemy.hp > 0) {
                                                val edx = obs.x - enemy.x
                                                val edy = obs.y - enemy.y
                                                val edist = sqrt(edx * edx + edy * edy)
                                                if (edist < 22f) {
                                                    obs.isDestroyed = true
                                                    enemies.forEach { nearEnemy ->
                                                        if (nearEnemy.hp > 0) {
                                                            val ndx = obs.x - nearEnemy.x
                                                            val ndy = obs.y - nearEnemy.y
                                                            val ndist = sqrt(ndx * ndx + ndy * ndy)
                                                            if (ndist < 75f) {
                                                                val dmg = 45
                                                                nearEnemy.hp = (nearEnemy.hp - dmg).coerceAtLeast(0)
                                                                nearEnemy.x -= (ndx / ndist) * 35f
                                                                nearEnemy.y -= (ndy / ndist) * 35f
                                                                
                                                                damageNumbers.add(
                                                                    IsoDamageNumber(
                                                                        id = System.nanoTime() + nearEnemy.id,
                                                                        text = "EXPLOSION -$dmg HP",
                                                                        x = nearEnemy.x,
                                                                        y = nearEnemy.y - 12f,
                                                                        color = QuantumNeonOrange
                                                                    )
                                                                )
                                                            }
                                                        }
                                                    }
                                                    
                                                    for (k in 0..16) {
                                                        val angle = k * (6.28318f / 17f)
                                                        val pSpeed = 60f + Random.nextFloat() * 40f
                                                        particles.add(
                                                            IsoParticle(
                                                                x = obs.x,
                                                                y = obs.y - 10f,
                                                                vx = cos(angle) * pSpeed,
                                                                vy = sin(angle) * pSpeed * 0.5f - 20f,
                                                                color = QuantumNeonOrange,
                                                                size = 7f,
                                                                life = 25
                                                            )
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        } else if (obs.type.startsWith("NPC_")) {
                            when (obs.type) {
                                "NPC_COMPANION_ENG" -> {
                                    val dx = playerX - obs.x
                                    val dy = playerY - obs.y
                                    val dist = sqrt(dx * dx + dy * dy)
                                    if (dist > 45f) {
                                        val moveSpeed = 35f
                                        obs.x += (dx / dist) * moveSpeed * delta
                                        obs.y += (dy / dist) * moveSpeed * delta
                                    }
                                    if (ticks % 90 == 0 && localPlayerHp < gameState.maxHealth && dist < 120f) {
                                        val healAmount = 10
                                        localPlayerHp = (localPlayerHp + healAmount).coerceAtMost(gameState.maxHealth)
                                        viewModel.updatePlayerHealth(localPlayerHp)
                                        
                                        damageNumbers.add(
                                            IsoDamageNumber(
                                                id = System.nanoTime() + obs.id,
                                                text = "+$healAmount HP Nano-Repair",
                                                x = playerX,
                                                y = playerY - 15f,
                                                color = QuantumNeonGreen
                                            )
                                        )
                                        
                                        for (i in 0..5) {
                                            particles.add(
                                                IsoParticle(
                                                    x = playerX + Random.nextFloat() * 20f - 10f,
                                                    y = playerY - Random.nextFloat() * 20f,
                                                    vx = Random.nextFloat() * 10f - 5f,
                                                    vy = -20f - Random.nextFloat() * 10f,
                                                    color = QuantumNeonGreen,
                                                    size = 4f,
                                                    life = 15
                                                )
                                            )
                                        }
                                    }
                                }
                                "NPC_GUARD" -> {
                                    if (ticks % 40 == 0) {
                                        var targetEnemy: IsoEnemy? = null
                                        var closestDist = 135f
                                        enemies.forEach { enemy ->
                                            if (enemy.hp > 0) {
                                                val edx = enemy.x - obs.x
                                                val edy = enemy.y - obs.y
                                                val edist = sqrt(edx * edx + edy * edy)
                                                if (edist < closestDist) {
                                                    closestDist = edist
                                                    targetEnemy = enemy
                                                }
                                            }
                                        }
                                        
                                        targetEnemy?.let { enemy ->
                                            val dmg = 15
                                            enemy.hp = (enemy.hp - dmg).coerceAtLeast(0)
                                            
                                            damageNumbers.add(
                                                IsoDamageNumber(
                                                    id = System.nanoTime() + enemy.id,
                                                    text = "-$dmg Guard Blaster",
                                                    x = enemy.x,
                                                    y = enemy.y - 12f,
                                                    color = obs.color
                                                )
                                            )
                                            
                                            for (step in 0..5) {
                                                val t = step / 5f
                                                particles.add(
                                                    IsoParticle(
                                                        x = obs.x * (1f - t) + enemy.x * t,
                                                        y = (obs.y - 24f) * (1f - t) + enemy.y * t,
                                                        vx = Random.nextFloat() * 10f - 5f,
                                                        vy = Random.nextFloat() * 10f - 5f,
                                                        color = obs.color,
                                                        size = 3.5f,
                                                        life = 10
                                                    )
                                                )
                                            }
                                        }
                                    }
                                }
                                "NPC_MERCHANT" -> {
                                    if (ticks % 40 == 0) {
                                        particles.add(
                                            IsoParticle(
                                                x = obs.x + Random.nextFloat() * 12f - 6f,
                                                y = obs.y - 18f,
                                                vx = Random.nextFloat() * 10f - 5f,
                                                vy = -15f - Random.nextFloat() * 10f,
                                                color = obs.color,
                                                size = 3f,
                                                life = 20
                                            )
                                        )
                                    }
                                }
                                "NPC_CHEMIST" -> {
                                    val dx = playerX - obs.x
                                    val dy = playerY - obs.y
                                    val dist = sqrt(dx * dx + dy * dy)
                                    if (ticks % 30 == 0) {
                                        particles.add(
                                            IsoParticle(
                                                x = obs.x + Random.nextFloat() * 16f - 8f,
                                                y = obs.y - 10f,
                                                vx = Random.nextFloat() * 12f - 6f,
                                                vy = -22f,
                                                color = obs.color,
                                                size = 4.5f,
                                                life = 25
                                            )
                                        )
                                    }
                                    if (dist < 45f && ticks % 80 == 0 && localPlayerHp < gameState.maxHealth) {
                                        localPlayerHp = (localPlayerHp + 5).coerceAtMost(gameState.maxHealth)
                                        viewModel.updatePlayerHealth(localPlayerHp)
                                        particles.add(IsoParticle(playerX, playerY - 10f, 0f, -30f, obs.color, 5f, 1f, 15))
                                    }
                                }
                                "NPC_ROGUE" -> {
                                    val dx = playerX - obs.x
                                    val dy = playerY - obs.y
                                    val dist = sqrt(dx * dx + dy * dy)
                                    if (ticks % 25 == 0) {
                                        particles.add(
                                            IsoParticle(
                                                x = obs.x + Random.nextFloat() * 14f - 7f,
                                                y = obs.y - 12f,
                                                vx = Random.nextFloat() * 8f - 4f,
                                                vy = -18f,
                                                color = obs.color,
                                                size = 3f,
                                                life = 18
                                            )
                                        )
                                    }
                                    if (dist < 45f && ticks % 40 == 0) {
                                        particles.add(IsoParticle(playerX, playerY, Random.nextFloat() * 10f - 5f, -5f, obs.color.copy(alpha = 0.5f), 5f, 1f, 12))
                                    }
                                }
                            }
                        }
                    }
                }

                delay(16)
            }
        }
    }

    // Dynamic Action Trigger (Melee strike or Ranged shot depending on equipped weapon)
    val performStrike: () -> Unit = {
        val weapon = gameState.currentWeapon
        if (weapon.type == WeaponType.MELEE) {
            if (!isAttacking) {
                isAttacking = true
                attackFrame = 0
                
                val range = 65f
                val slashX = playerX + playerDirX * 32f
                val slashY = playerY + playerDirY * 32f
                
                for (i in 0..10) {
                    particles.add(
                        IsoParticle(
                            x = slashX + Random.nextFloat() * 16f - 8f,
                            y = slashY + Random.nextFloat() * 16f - 8f,
                            vx = playerDirX * (80f + Random.nextFloat() * 40f) + Random.nextFloat() * 20f - 10f,
                            vy = playerDirY * (80f + Random.nextFloat() * 40f) + Random.nextFloat() * 20f - 10f,
                            color = QuantumNeonPurple,
                            size = 8f,
                            life = 15
                        )
                    )
                }
                
                val eIter = enemies.iterator()
                while (eIter.hasNext()) {
                    val enemy = eIter.next()
                    val edx = enemy.x - slashX
                    val edy = enemy.y - slashY
                    val edist = sqrt(edx * edx + edy * edy)
                    
                    if (edist < range) {
                        enemy.hitCooldown = 12
                        enemy.state = "HIT"
                        
                        val damage = ((gameState.currentWeapon.baseAtk + gameState.totalAtkBonus) * (1f + gameState.level * 0.12f)).toInt() + Random.nextInt(-8, 12)
                        enemy.hp = (enemy.hp - damage).coerceAtLeast(0)
                        
                        damageNumbers.add(
                            IsoDamageNumber(
                                id = System.nanoTime(),
                                text = "⚔️ $damage",
                                x = enemy.x,
                                y = enemy.y - 12f,
                                color = QuantumNeonOrange
                            )
                        )
                        
                        for (i in 0..5) {
                            particles.add(
                                IsoParticle(
                                    x = enemy.x,
                                    y = enemy.y,
                                    vx = Random.nextFloat() * 120f - 60f,
                                    vy = Random.nextFloat() * 120f - 60f,
                                    color = QuantumNeonRed,
                                    size = 5f,
                                    life = 10
                                )
                            )
                        }
                        
                        if (enemy.hp <= 0) {
                            eIter.remove()
                            handleEnemyDefeat(enemy)
                        }
                    }
                }
    
                // Check wildlife hit/harvest
                val wIter = wildlifeList.iterator()
                while (wIter.hasNext()) {
                    val wildlife = wIter.next()
                    val wdx = wildlife.x - slashX
                    val wdy = wildlife.y - slashY
                    val wdist = sqrt(wdx * wdx + wdy * wdy)
                    
                    if (wdist < range) {
                        wildlife.hitCooldown = 15
                        val dropItem = wildlife.drops.randomOrNull() ?: "Biomass"
                        val creditReward = when (wildlife.rarity) {
                            "Common" -> Random.nextInt(40, 85)
                            "Rare" -> Random.nextInt(90, 160)
                            "Epic" -> Random.nextInt(200, 350)
                            else -> Random.nextInt(400, 800)
                        }
                        val xpReward = when (wildlife.rarity) {
                            "Common" -> 50
                            "Rare" -> 120
                            "Epic" -> 250
                            else -> 500
                        }
                        
                        for (i in 0..8) {
                            particles.add(
                                IsoParticle(
                                    x = wildlife.x,
                                    y = wildlife.y,
                                    vx = Random.nextFloat() * 140f - 70f,
                                    vy = Random.nextFloat() * 140f - 70f,
                                    color = wildlife.color,
                                    size = 6f,
                                    life = 12
                                )
                            )
                        }
                        
                        damageNumbers.add(
                            IsoDamageNumber(
                                id = System.nanoTime(),
                                text = "💥 Harvest: $dropItem",
                                x = wildlife.x,
                                y = wildlife.y - 12f,
                                color = QuantumNeonGreen
                            )
                        )
                        damageNumbers.add(
                            IsoDamageNumber(
                                id = System.nanoTime() + 1,
                                text = "+$creditReward Credits",
                                x = wildlife.x,
                                y = wildlife.y - 28f,
                                color = QuantumNeonOrange
                            )
                        )
                        damageNumbers.add(
                            IsoDamageNumber(
                                id = System.nanoTime() + 2,
                                text = "+$xpReward XP",
                                x = playerX,
                                y = playerY - 30f,
                                color = QuantumNeonBlue
                            )
                        )
                        
                        collectibles.add(
                            IsoCollectible(
                                id = System.nanoTime() + 3,
                                type = dropItem,
                                x = wildlife.x,
                                y = wildlife.y,
                                amount = when (wildlife.rarity) {
                                    "Common" -> Random.nextInt(1, 3)
                                    "Rare" -> Random.nextInt(3, 6)
                                    "Epic" -> Random.nextInt(5, 10)
                                    else -> Random.nextInt(10, 20)
                                },
                                symbol = "📦"
                            )
                        )
                        
                        viewModel.addResources(creditReward, xpReward / 4, xpReward)
                        wIter.remove()
                    }
                }
                
                // Check destructible obstacles
                obstacles.forEach { obs ->
                    if (obs.isDestructible && !obs.isDestroyed) {
                        val odx = obs.x - slashX
                        val ody = obs.y - slashY
                        val odist = sqrt(odx * odx + ody * ody)
                        if (odist < range) {
                            val damage = ((gameState.currentWeapon.baseAtk + gameState.totalAtkBonus) * (1f + gameState.level * 0.12f)).toInt() + Random.nextInt(-5, 10)
                            obs.hp = (obs.hp - damage).coerceAtLeast(0)
                            
                            for (i in 0..5) {
                                particles.add(
                                    IsoParticle(
                                        x = obs.x,
                                        y = obs.y,
                                        vx = Random.nextFloat() * 100f - 50f,
                                        vy = Random.nextFloat() * 100f - 50f,
                                        color = obs.color,
                                        size = 5f,
                                        life = 10
                                    )
                                )
                            }
                            
                            damageNumbers.add(
                                IsoDamageNumber(
                                    id = System.nanoTime(),
                                    text = "💥 $damage",
                                    x = obs.x,
                                    y = obs.y - 12f,
                                    color = obs.color
                                )
                            )
                            
                            if (obs.hp <= 0) {
                                handleCrateDestruction(obs)
                            }
                        }
                    }
                }
            }
        } else {
            // RANGED ATTACK: Shoot projectile particle in facing direction
            val bulletColor = when (weapon.type) {
                WeaponType.PISTOL -> QuantumNeonBlue
                WeaponType.RIFLE -> QuantumNeonOrange
                WeaponType.HEAVY -> QuantumNeonRed
                WeaponType.ENERGY -> QuantumNeonGreen
                WeaponType.QUANTUM -> QuantumNeonPurple
                else -> Color.White
            }
            val bulletSize = when (weapon.type) {
                WeaponType.PISTOL -> 7f
                WeaponType.RIFLE -> 8f
                WeaponType.HEAVY -> 15f
                WeaponType.ENERGY -> 11f
                WeaponType.QUANTUM -> 13f
                else -> 8f
            }
            
            particles.add(
                IsoParticle(
                    x = playerX + playerDirX * 18f,
                    y = playerY + playerDirY * 18f,
                    vx = playerDirX * 280f,
                    vy = playerDirY * 280f,
                    color = bulletColor,
                    size = bulletSize,
                    life = 40,
                    isPlayerProjectile = true
                )
            )
            
            // Tiny muzzle sparks
            for (i in 0..3) {
                particles.add(
                    IsoParticle(
                        x = playerX + playerDirX * 18f,
                        y = playerY + playerDirY * 18f,
                        vx = playerDirX * 60f + Random.nextFloat() * 40f - 20f,
                        vy = playerDirY * 60f + Random.nextFloat() * 40f - 20f,
                        color = bulletColor.copy(alpha = 0.6f),
                        size = 4f,
                        life = 8
                    )
                )
            }
        }
    }

    // Quantum Special Ability Trigger (Consumes 20 MP to deal massive AoE damage & display dynamic fx)
    val performQuantumSkill: () -> Unit = {
        if (gameState.mp >= 20) {
            viewModel.consumePlayerMp(20)
            
            // Emit 45 expanding neon-purple waves outwards
            for (i in 0..45) {
                val angle = (i / 45f) * 2 * Math.PI
                val vx = cos(angle).toFloat() * 180f
                val vy = sin(angle).toFloat() * 180f
                particles.add(
                    IsoParticle(
                        x = playerX,
                        y = playerY,
                        vx = vx,
                        vy = vy,
                        color = QuantumNeonPurple,
                        size = 12f,
                        life = 35,
                        isQuantumAbility = true
                    )
                )
            }
            
            damageNumbers.add(
                IsoDamageNumber(
                    id = System.nanoTime(),
                    text = "🌌 QUANTUM BURST! 🌌",
                    x = playerX,
                    y = playerY - 32f,
                    color = QuantumNeonPurple
                )
            )
            
            // Deal massive damage to ALL enemies and destructible crates nearby!
            val burstRange = 140f
            val eIter = enemies.iterator()
            while (eIter.hasNext()) {
                val enemy = eIter.next()
                val edx = enemy.x - playerX
                val edy = enemy.y - playerY
                val edist = sqrt(edx * edx + edy * edy)
                if (edist < burstRange) {
                    enemy.hitCooldown = 15
                    enemy.state = "HIT"
                    val dmg = 180 + gameState.level * 30 + Random.nextInt(-15, 25)
                    enemy.hp = (enemy.hp - dmg).coerceAtLeast(0)
                    
                    damageNumbers.add(
                        IsoDamageNumber(
                            id = System.nanoTime() + enemy.id,
                            text = "💥 $dmg QUANTUM",
                            x = enemy.x,
                            y = enemy.y - 12f,
                            color = QuantumNeonPurple
                        )
                    )
                    
                    // Burst particles on enemy
                    for (k in 0..6) {
                        particles.add(
                            IsoParticle(
                                x = enemy.x,
                                y = enemy.y,
                                vx = Random.nextFloat() * 140f - 70f,
                                vy = Random.nextFloat() * 140f - 70f,
                                color = QuantumNeonPurple,
                                size = 6f,
                                life = 15
                            )
                        )
                    }
                    
                    if (enemy.hp <= 0) {
                        eIter.remove()
                        handleEnemyDefeat(enemy)
                    }
                }
            }
            
            // Also hit destructible crates
            obstacles.forEach { obs ->
                if (obs.isDestructible && !obs.isDestroyed) {
                    val odx = obs.x - playerX
                    val ody = obs.y - playerY
                    val odist = sqrt(odx * odx + ody * ody)
                    if (odist < burstRange) {
                        val dmg = 180 + gameState.level * 30 + Random.nextInt(-10, 20)
                        obs.hp = (obs.hp - dmg).coerceAtLeast(0)
                        damageNumbers.add(IsoDamageNumber(System.nanoTime(), "💥 $dmg QUANTUM", obs.x, obs.y - 12f, QuantumNeonPurple))
                        if (obs.hp <= 0) {
                            handleCrateDestruction(obs)
                        }
                    }
                }
            }
        } else {
            // Out of MP warning!
            damageNumbers.add(
                IsoDamageNumber(
                    id = System.nanoTime(),
                    text = "NO ENERGY (NEED 20 MP)",
                    x = playerX,
                    y = playerY - 32f,
                    color = QuantumNeonRed
                )
            )
        }
    }
    
    // Shield Trigger Action
    val performShield: () -> Unit = {
        if (shieldActiveTime <= 0) {
            shieldActiveTime = 180
            for (i in 0..12) {
                val ang = Random.nextFloat() * 6.28f
                particles.add(
                    IsoParticle(
                        x = playerX + cos(ang) * 20f,
                        y = playerY + sin(ang) * 20f,
                        vx = cos(ang) * 15f,
                        vy = sin(ang) * 15f,
                        color = QuantumNeonBlue,
                        size = 5f,
                        life = 25
                    )
                )
            }
        }
    }
    
    // Dash Trigger Action
    val performDash: () -> Unit = {
        if (dashActiveTime <= 0) {
            dashActiveTime = 12
            playerX = (playerX + playerDirX * 50f).coerceIn(30f, 370f)
            playerY = (playerY + playerDirY * 50f).coerceIn(30f, 370f)
            
            for (i in 0..10) {
                particles.add(
                    IsoParticle(
                        x = playerX - playerDirX * i * 4f,
                        y = playerY - playerDirY * i * 4f,
                        vx = 0f,
                        vy = 0f,
                        color = QuantumNeonPurple.copy(alpha = 0.5f),
                        size = 12f,
                        life = 12
                    )
                )
            }
        }
    }
    
    // Interact / Hack Trigger Action
    val performInteract: () -> Unit = {
        activeConsoleNearby?.let { console ->
            if (console.type.startsWith("NPC_")) {
                // Play interactive sound
                try {
                    val toneGen = android.media.ToneGenerator(android.media.AudioManager.STREAM_MUSIC, 100)
                    toneGen.startTone(android.media.ToneGenerator.TONE_CDMA_PIP, 150)
                } catch (e: Exception) {}

                // Spawn some cool digital floaty particles
                for (i in 0..12) {
                    val ang = Random.nextFloat() * 6.28f
                    particles.add(
                        IsoParticle(
                            x = console.x,
                            y = console.y,
                            vx = cos(ang) * (30f + Random.nextFloat() * 20f),
                            vy = sin(ang) * (30f + Random.nextFloat() * 20f) - 20f,
                            color = console.color,
                            size = 4f,
                            life = 25
                        )
                    )
                }

                // Determine dialogue text
                val msg = when (console.type) {
                    "NPC_MERCHANT" -> "MERCHANT: 'Greetings, sector traveler. Credits streams are encrypted. Ready to trade high-tier bio-mechanical mods?'"
                    "NPC_GUARD" -> "GUARD: 'Reputation scan complete. Aurelian Aegis barriers are stable. Standing watch against Technopunk raider infiltrations.'"
                    "NPC_CHEMIST" -> "CHEMIST: 'Subatomic quantum crystallization rate is 98.4%. If you require nanite stabilization or bio-repair packs, step closer.'"
                    "NPC_ROGUE" -> "OUTLAW: 'Hey kid, stay cool. Technopunks are mapping the nearby credits caches. Keep this encounter off the network.'"
                    "NPC_COMPANION_ENG" -> "COMPANION: 'Nano-Repair Matrix online. Monitoring host life signatures at 100% capacity.'"
                    "NPC_EXPLORER" -> "NOMAD: 'I have cataloged three void portals in this sector. The quantum effects are increasing. Be careful out there.'"
                    else -> "OPERATIVE: 'Sector grid connection established. High-speed encrypted transmission channel is secure and active.'"
                }

                activeNpcDialogue = console
                activeDialogueText = msg

                damageNumbers.add(
                    IsoDamageNumber(
                        id = System.nanoTime(),
                        text = "💬 CONNECTED",
                        x = console.x,
                        y = console.y - 20f,
                        color = console.color
                    )
                )
            } else if (console.type == "CONTAINER" || console.type == "CRATE" || console.type.startsWith("CRATE")) {
                // Play interactive opening sound
                try {
                    val toneGen = android.media.ToneGenerator(android.media.AudioManager.STREAM_MUSIC, 100)
                    toneGen.startTone(android.media.ToneGenerator.TONE_PROP_BEEP2, 180)
                } catch (e: Exception) {}

                // Spawn cool fountain of gold/purple resource particles shooting up!
                for (i in 0..25) {
                    val ang = Random.nextFloat() * 6.28f
                    val speedVal = 40f + Random.nextFloat() * 60f
                    particles.add(
                        IsoParticle(
                            x = console.x,
                            y = console.y,
                            vx = cos(ang) * speedVal * 0.4f,
                            vy = -speedVal - Random.nextFloat() * 40f,
                            color = if (Random.nextBoolean()) QuantumNeonGreen else console.color,
                            size = 5f + Random.nextFloat() * 3f,
                            life = 35
                        )
                    )
                }

                // Award resources
                val creditsGain = Random.nextInt(100, 250)
                val nanitesGain = Random.nextInt(20, 50)
                viewModel.addResources(creditsGain, nanitesGain, 150)

                // Drop custom raw crafting material
                val materials = listOf(
                    Triple("Alloy Plate", "⚙️", "Scrap"),
                    Triple("Nano Fiber", "🧵", "Crafting Material"),
                    Triple("Void Crystal", "🔮", "Crafting Material"),
                    Triple("Quantum Core", "🌀", "Crafting Material")
                )
                val pickedMat = materials.random()
                val matQty = Random.nextInt(1, 3)
                viewModel.addItemToInventory(
                    pickedMat.first,
                    pickedMat.third,
                    pickedMat.second,
                    matQty,
                    "A raw component salvaged from sector canisters."
                )

                // Spawn on-the-ground collectibles (gold credits, purple nanites) around the opened container
                for (k in 0..3) {
                    val rx = console.x + (Random.nextFloat() * 30f - 15f)
                    val ry = console.y + (Random.nextFloat() * 30f - 15f)
                    collectibles.add(
                        IsoCollectible(
                            id = System.nanoTime() + k,
                            type = if (k % 2 == 0) "Credits" else "Nanites",
                            x = rx,
                            y = ry,
                            amount = if (k % 2 == 0) creditsGain / 2 else nanitesGain,
                            symbol = if (k % 2 == 0) "💎" else "💠",
                            isMagnetized = false
                        )
                    )
                }

                damageNumbers.add(
                    IsoDamageNumber(
                        id = System.nanoTime(),
                        text = "📦 OPENED: +$creditsGain CR, +$nanitesGain NA",
                        x = console.x,
                        y = console.y - 15f,
                        color = QuantumNeonGreen
                    )
                )

                console.isDestroyed = true
            } else if (console.type == "DOOR" || console.type.startsWith("DOOR")) {
                // Play interactive door slide/unlock sound
                try {
                    val toneGen = android.media.ToneGenerator(android.media.AudioManager.STREAM_MUSIC, 100)
                    toneGen.startTone(android.media.ToneGenerator.TONE_SUP_CONFIRM, 200)
                } catch (e: Exception) {}

                // Spawn laser-dissolving horizontal particles
                for (i in 0..20) {
                    particles.add(
                        IsoParticle(
                            x = console.x + (Random.nextFloat() * 30f - 15f),
                            y = console.y - Random.nextFloat() * 30f,
                            vx = Random.nextFloat() * 80f - 40f,
                            vy = Random.nextFloat() * 20f - 10f,
                            color = console.color,
                            size = 4f,
                            life = 15
                        )
                    )
                }

                damageNumbers.add(
                    IsoDamageNumber(
                        id = System.nanoTime(),
                        text = "🚪 ACCESS GRANTED",
                        x = console.x,
                        y = console.y - 15f,
                        color = console.color
                    )
                )

                console.isDestroyed = true
            } else if (console.type == "QUANTUM_GATE") {
                viewModel.discoverGate("gate_${selectedBiome.name.lowercase()}")
                activeMode = 12
                
                try {
                    val toneGen = android.media.ToneGenerator(android.media.AudioManager.STREAM_MUSIC, 100)
                    toneGen.startTone(android.media.ToneGenerator.TONE_SUP_CONFIRM, 300)
                } catch (e: Exception) {}

                for (i in 0..30) {
                    val ang = i * (6.28f / 30f)
                    particles.add(
                        IsoParticle(
                            x = console.x,
                            y = console.y,
                            vx = cos(ang) * 50f,
                            vy = sin(ang) * 50f,
                            color = console.color,
                            size = 5f,
                            life = 30
                        )
                    )
                }

                damageNumbers.add(
                    IsoDamageNumber(
                        id = System.nanoTime(),
                        text = "🌀 PORTAL OPENED: WARP INTERFACE ACTIVE",
                        x = console.x,
                        y = console.y - 20f,
                        color = console.color
                    )
                )
            } else if (console.type.startsWith("BUILDING") || console.type == "INTERNAL_MODULE" || console.type.startsWith("PROP_")) {
                activeInteractedStructure = console
            } else {
                // Standard terminal hack
                try {
                    val toneGen = android.media.ToneGenerator(android.media.AudioManager.STREAM_MUSIC, 100)
                    toneGen.startTone(android.media.ToneGenerator.TONE_PROP_BEEP, 120)
                } catch (e: Exception) {}

                for (i in 0..15) {
                    val ang = Random.nextFloat() * 6.28f
                    particles.add(
                        IsoParticle(
                            x = console.x,
                            y = console.y,
                            vx = cos(ang) * (60f + Random.nextFloat() * 40f),
                            vy = sin(ang) * (60f + Random.nextFloat() * 40f),
                            color = console.color,
                            size = 6f,
                            life = 20
                        )
                    )
                }
                
                viewModel.addResources(150, 35, 200)
                
                damageNumbers.add(
                    IsoDamageNumber(
                        id = System.nanoTime(),
                        text = "SYS_HACKED: +200 XP",
                        x = console.x,
                        y = console.y - 15f,
                        color = console.color
                    )
                )
                
                console.isDestroyed = true
            }
        }
    }
    
