                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = "${ds.name.uppercase()} (CLASS ${ds.level})",
                                        fontSize = 10.sp,
                                        fontFamily = FontFamily.Monospace,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(ds.colorVal.toULong())
                                    )
                                    Text(
                                        text = "Interactive Yield: +$bonusCrd Crd / +$bonusNnt Nnt",
                                        fontSize = 8.sp,
                                        fontFamily = FontFamily.Monospace,
                                        color = QuantumGrayText
                                    )
                                }
                                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                    CyberButton(
                                        onClick = {
                                            viewModel.addResources(bonusCrd, bonusNnt, 20)
                                            damageNumbers.add(
                                                IsoDamageNumber(
                                                    id = System.nanoTime(),
                                                    text = "+$bonusCrd Credits harvested!",
                                                    x = playerX,
                                                    y = playerY - 30f,
                                                    color = Color(ds.colorVal.toULong())
                                                )
                                            )
                                        },
                                        text = "Harvest",
                                        color = Color(ds.colorVal.toULong()),
                                        modifier = Modifier.height(28.dp)
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

