fun translateGdScriptToKotlin(gdscript: String): String {
    return gdscript
        .replace("extends CharacterBody2D", "class CompanionController(val body: BoxScope) : GameEngineEntity")
        .replace("extends StaticBody2D", "class StaticStationController(val canvas: Canvas) : GameEngineEntity")
        .replace("extends Node2D", "class SceneController : GameEngineEntity")
        .replace("extends Area2D", "class TriggerZoneController : GameEngineEntity")
        .replace("extends GPUParticles2D", "class ParticleController : GameEngineEntity")
        .replace("class_name IsometricBuilding", "// Native Android Building Logic")
        .replace("signal building_hacked(faction_alignment: String)", "val onBuildingHacked = MutableSharedFlow<String>()")
        .replace("signal structure_deployed(building_id: String, position: Vector2)", "val onStructureDeployed = MutableSharedFlow<Pair<String, Offset>>()")
        .replace("@export_category", "// Category")
        .replace("@export_group", "// Group")
        .replace("@export var", "var")
        .replace("@onready var", "val")
        .replace("var base_texture: Texture2D", "var baseTexture: ImageBitmap")
        .replace("var wall_texture: Texture2D", "var wallTexture: ImageBitmap")
        .replace("var roof_texture: Texture2D", "var roofTexture: ImageBitmap")
        .replace("var detail_texture: Texture2D", "var detailTexture: ImageBitmap")
        .replace("func _ready() -> void:", "override fun onStart() {")
        .replace("func _ready():", "override fun onStart() {")
        .replace("func _process(delta: float) -> void:", "override fun onUpdate(delta: Float) {")
        .replace("func _process(delta):", "override fun onUpdate(delta: Float) {")
        .replace("func _physics_process(delta: float) -> void:", "override fun onPhysicsTick(delta: Float) {")
        .replace("func _physics_process(delta):", "override fun onPhysicsTick(delta: Float) {")
        .replace("self.", "this.")
        .replace("Vector2.ZERO", "Offset.Zero")
        .replace("Vector2(", "Offset(")
        .replace("Color(", "Color(")
        .replace("var velocity = Offset.Zero", "var velocity = Offset(0f, 0f)")
        .replace("move_and_slide()", "body.moveAndSlide(velocity)")
        .replace("queue_free()", "destroy()")
        .replace("get_node(", "findViewById(")
        .replace("connect(", "addListener(")
        .replace("# Godot 4.x GDScript:", "// Native Kotlin & Compose Controller:")
        .replace("#", "//")
        .replace("func ", "fun ")
        .replace(":\n", " {\n")
        .replace("pass", "")
}

fun getComposeComponentForNode(nodeName: String): String {
    return when (nodeName) {
        "StaticBody2D" -> "Canvas with drawRect & Modifier.pointerInput"
        "CharacterBody2D" -> "Box with Modifier.offset & AnimatedVisibility"
        "Area2D" -> "Box with Modifier.combinedClickable"
        "GPUParticles2D" -> "Compose Canvas with Particle Loop"
        "CPUParticles2D" -> "Compose Canvas with Particle Loop"
        "Node2D" -> "Compose Canvas with graphicsLayer"
        else -> "Jetpack Compose / Modifier"
    }
}

fun getDynamicGdScript(vfx: VfxElement, scale: Float, count: Int): String {
    val scaleStr = String.format(java.util.Locale.US, "%.2f", scale)
    val countStr = count.toString()
    return when (vfx.id) {
        "melee_slash_arc" -> """
// ⚡ NATIVE JETPACK COMPOSE HIGH-PERFORMANCE SWEEP PARTICLE SYSTEM
// Implementation using pre-allocated objects & hardware accelerated Canvas

class ComposeSlashVfxEngine(val maxParticles: Int = $countStr) {
    private val particles = Array(maxParticles) { SlashParticle() }
    private val path = Path()
    private val brush = Brush.linearGradient(
        colors = listOf(Color(0xFF00E5FF), Color(0xFFD500F9), Color.Transparent)
    )

    fun draw(drawScope: DrawScope, scale: Float = $scaleStr) = with(drawScope) {
        val center = size.center
        val radius = 120dp.toPx() * scale
        
        // Draw primary blade sweep trail with Additive Blending
        path.reset()
        path.arcTo(
            rect = Rect(center - Offset(radius, radius), center + Offset(radius, radius)),
            startAngleDegrees = -120f,
            sweepAngleDegrees = 90f,
            forceMoveTo = true
        )
        drawPath(
            path = path,
            brush = brush,
            style = Stroke(width = 8dp.toPx(), cap = StrokeCap.Round),
            blendMode = BlendMode.Screen
        )
        
        // Render glowing energy sparks
        particles.forEach { p ->
            p.update()
            drawCircle(
                color = p.color.copy(alpha = p.alpha),
                radius = p.size * scale,
                center = center + Offset(p.x, p.y),
                blendMode = BlendMode.Screen
            )
        }
    }
}
        """.trimIndent()
        
        "plasma_ring_aoe" -> """
// ⚡ NATIVE JETPACK COMPOSE RADIAL ADDITIVE BLAST
// Optimized for high-end Android (Samsung Fold 6, OnePlus 15)

@Composable
fun PlasmaRingAoeVfx(
    modifier: Modifier = Modifier,
    scale: Float = $scaleStr,
    isPlaying: Boolean = true
) {
    val scaleAnim by animateFloatAsState(
        targetValue = if (isPlaying) scale * 2f else 0.5f,
        animationSpec = infiniteRepeatable(
            animation = tween(1200, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        )
    )
    
    val alphaAnim by animateFloatAsState(
        targetValue = if (isPlaying) 0f else 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(1200, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        )
    )

    Canvas(modifier = modifier.fillMaxSize().graphicsLayer(alpha = alphaAnim)) {
        val center = size.center
        val maxRadius = 150dp.toPx() * scaleAnim
        
        // Outer Shockwave Glow Ring
        drawCircle(
            brush = Brush.radialGradient(
                colors = listOf(Color(0xFFFF1744).copy(alpha = 0.8f), Color.Transparent),
                center = center,
                radius = maxRadius
            ),
            radius = maxRadius,
            blendMode = BlendMode.Screen
        )
        
        // High-frequency energy core border
        drawCircle(
            color = Color(0xFFFFD600),
            radius = maxRadius * 0.9f,
            style = Stroke(width = 4dp.toPx()),
            blendMode = BlendMode.Screen
        )
    }
}
        """.trimIndent()

        "arcane_lightning" -> """
// ⚡ FRACTAL BRANCHING LIGHTNING EMITTER IN JETPACK COMPOSE
// Hardware-accelerated drawing on native Android graphics rendering pipeline

fun DrawScope.drawArcaneLightning(
    start: Offset,
    end: Offset,
    branches: Int = 4,
    scale: Float = $scaleStr
) {
    val points = mutableListOf<Offset>()
    points.add(start)
    
    val segments = 8
    val delta = (end - start) / segments.toFloat()
    
    var current = start
    for (i in 1 until segments) {
        val mid = start + delta * i.toFloat()
        // Orthogonal offset for jagged fractal lightning aesthetics
        val ortho = Offset(-delta.y, delta.x).normalize() * 
                    (Random.nextFloat() - 0.5f) * 40dp.toPx() * scale
        current = mid + ortho
        points.add(current)
    }
    points.add(end)

    // Render primary high-voltage beam with dynamic additive color mapping
    for (i in 0 until points.lastIndex) {
        drawLine(
            color = Color(0xFF00E5FF),
            start = points[i],
            end = points[i + 1],
            strokeWidth = 5dp.toPx() * scale,
            cap = StrokeCap.Round,
            blendMode = BlendMode.Screen
        )
        // Secondary Inner Core White Heat Beam
        drawLine(
            color = Color.White,
            start = points[i],
            end = points[i + 1],
            strokeWidth = 2dp.toPx() * scale,
            cap = StrokeCap.Round,
            blendMode = BlendMode.Screen
        )
    }
}
        """.trimIndent()

        else -> """
// ⚡ HIGH-PERFORMANCE COMPOSABLE PARTICLE ENGINE
// Configured with $countStr dynamic particles, scale = $scaleStr
// Leverages DrawScope blending and system navigation bar safe bounds

class ComposeGpuVfxEngine(val count: Int = $countStr, val scale: Float = $scaleStr) {
    private val particles = List(count) {
        ComposeParticle(
            color = Color(0xFFD500F9),
            angle = Random.nextFloat() * 360f,
            velocity = (2f + Random.nextFloat() * 5f)
        )
    }

    fun render(drawScope: DrawScope) = with(drawScope) {
        val origin = size.center
        particles.forEach { p ->
            p.update()
            drawCircle(
                color = p.color.copy(alpha = p.alpha),
                radius = 4dp.toPx() * scale * p.scale,
                center = origin + Offset(p.x, p.y),
                blendMode = BlendMode.Screen
            )
        }
    }
}
        """.trimIndent()
    }
}

fun getDynamicSetupInstructions(vfx: VfxElement, scale: Float, count: Int): String {
    return when (vfx.id) {
        "melee_slash_arc" -> """
1. Instantiate a custom drawing class inside your Composable, keeping allocations OUT of the DrawScope to avoid Garbage Collector (GC) pressure.
2. Setup a stateful Canvas: Canvas(modifier = Modifier.fillMaxSize().graphicsLayer(clip = false))
3. Use DrawScope.drawPath to render the high-frequency plasma blade sweep curve with a LinearGradient Brush.
4. Pass BlendMode.Screen to enable native GPU additive glow shading on the canvas draw operations.
5. Setup a high-refresh Game Loop (using a coroutine Channel or target 60FPS tick via Flow) to update particle physics and trigger redraws.
""".trimIndent()

        "plasma_ring_aoe" -> """
1. Configure a state-driven drawing pipeline using Jetpack Compose dynamic transition animation loops.
2. Use animateFloatAsState to transition the shockwave expansion radius and alpha fadeout.
3. Call DrawScope.drawCircle using Brush.radialGradient to simulate the plasma heat-shimmer core.
4. Set hardware acceleration explicitly by wrapping the Canvas with modifier.graphicsLayer(renderEffect = ...).
5. Leverage dynamic BlendMode.Screen to allow plasma colors to additively saturate over overlapping screen backgrounds.
""".trimIndent()

        "arcane_lightning" -> """
1. Generate jagged lightning line coordinates using midpoint displacement (fractal branching recursion).
2. Inside Compose Canvas, render the branching paths by sequentially calling DrawScope.drawLine.
3. Draw two layers: a thicker outer neon cyan glow line (e.g. 6dp) and a thinner inner hot white core (2dp) for full electric realism.
4. Apply graphicsLayer modifier to the Canvas to handle hardware-accelerated drawing and automatic frame cache management.
5. Limit fractal depth to 3 levels on mobile hardware to prevent canvas draw overhead and maintain locked 60 FPS on Android devices.
""".trimIndent()

        else -> """
1. Setup a persistent particle array inside a remember {} block to prevent frame-by-frame heap allocations during standard composition.
2. Inside the Compose Canvas DrawScope, iterate over the particle array, updating positions and drawing circles.
3. Always configure graphicsLayer(clip = false) on your Composable modifier to ensure particles can drift beyond the strict layouts of parent composables.
4. Apply BlendMode.Screen to allow overlapping particles to merge into brilliant neon highlights.
5. Scale all dimensions using LocalDensity.current to translate raw design dp/sp dimensions into exact system pixels.
""".trimIndent()
    }
}

fun triggerVfxBurst(vfxId: String, simulatedParticles: androidx.compose.runtime.snapshots.SnapshotStateList<LocalSimParticle>, particleCount: Float) {
    val burstLimit = (particleCount * 0.8f).toInt().coerceAtLeast(10).coerceAtMost(200)
    when (vfxId) {
        "melee_slash_arc" -> {
            repeat(burstLimit) { i ->
                val progress = i.toFloat() / burstLimit.toFloat()
                val ang = (progress * Math.PI - Math.PI/4).toFloat()
                val R = 75f
                val px = 250f + cos(ang) * R
                val py = 160f + sin(ang) * R
                simulatedParticles.add(
                    LocalSimParticle(
                        id = Random.nextLong(),
                        x = px,
                        y = py,
                        vx = cos(ang + Math.PI.toFloat()/2) * (2f + Random.nextFloat() * 4f),
                        vy = sin(ang + Math.PI.toFloat()/2) * (2f + Random.nextFloat() * 4f),
                        color = Color(0xFFFF6D00),
                        size = 3f + Random.nextFloat() * 5f,
                        alpha = 1f,
                        maxLife = 35 + Random.nextInt(20),
                        life = 35 + Random.nextInt(20),
                        type = "spark"
                    )
                )
            }
        }
        "plasma_ring_aoe" -> {
            repeat(burstLimit) {
                val ang = Random.nextFloat() * 2 * Math.PI.toFloat()
                val speed = 2f + Random.nextFloat() * 5f
                simulatedParticles.add(
                    LocalSimParticle(
                        id = Random.nextLong(),
                        x = 250f,
                        y = 160f,
                        vx = cos(ang) * speed,
                        vy = sin(ang) * speed,
                        color = Color(0xFFFF3D00),
                        size = 4f + Random.nextFloat() * 6f,
                        alpha = 1f,
                        maxLife = 40,
                        life = 40,
                        type = "ring_dot"
                    )
                )
            }
        }
        "arcane_lightning" -> {
            repeat(burstLimit) {
                val ang = (Random.nextFloat() * Math.PI + Math.PI).toFloat() // outwards and upwards
                val speed = 3f + Random.nextFloat() * 6f
                simulatedParticles.add(
                    LocalSimParticle(
                        id = Random.nextLong(),
                        x = 250f,
                        y = 290f,
                        vx = cos(ang) * speed,
                        vy = sin(ang) * speed - 1f,
                        color = Color(0xFF00E5FF),
                        size = 2f + Random.nextFloat() * 4f,
                        alpha = 1f,
                        maxLife = 35,
                        life = 35,
                        type = "lightning_spark"
                    )
                )
            }
        }
        "fission_explosion" -> {
            repeat(burstLimit) {
                val ang = Random.nextFloat() * 2 * Math.PI.toFloat()
                val speed = 2f + Random.nextFloat() * 10f
                simulatedParticles.add(
                    LocalSimParticle(
                        id = Random.nextLong(),
                        x = 250f,
                        y = 160f,
                        vx = cos(ang) * speed,
                        vy = sin(ang) * speed,
                        color = if (Random.nextBoolean()) Color(0xFFFFD600) else Color(0xFFFF1744),
                        size = 4f + Random.nextFloat() * 10f,
                        alpha = 1f,
                        maxLife = 45 + Random.nextInt(25),
                        life = 45 + Random.nextInt(25),
                        type = "explosion_shard"
                    )
                )
            }
        }
        "level_up_wings" -> {
            repeat(burstLimit) { i ->
                val isLeft = i % 2 == 0
                val angleBias = if (isLeft) (3 * Math.PI / 4).toFloat() else (Math.PI / 4).toFloat()
                val speed = 2f + Random.nextFloat() * 4f
                val px = if (isLeft) 235f else 265f
                val py = 160f
                simulatedParticles.add(
                    LocalSimParticle(
                        id = Random.nextLong(),
                        x = px,
                        y = py,
                        vx = cos(angleBias + (Random.nextFloat() - 0.5f) * 0.4f).toFloat() * speed,
                        vy = -speed - Random.nextFloat() * 2f,
                        color = Color(0xFFFFD600),
                        size = 4f + Random.nextFloat() * 5f,
                        alpha = 1f,
                        maxLife = 45,
                        life = 45,
                        type = "wing"
                    )
                )
            }
        }
        "cyber_assembler" -> {
            repeat(burstLimit) {
                simulatedParticles.add(
                    LocalSimParticle(
                        id = Random.nextLong(),
                        x = 210f + Random.nextFloat() * 80f,
                        y = 160f,
                        vx = (Random.nextFloat() - 0.5f) * 4f,
                        vy = (Random.nextFloat() - 0.5f) * 1.5f,
                        color = Color(0xFF2979FF),
                        size = 3f + Random.nextFloat() * 3f,
                        alpha = 1f,
                        maxLife = 25,
                        life = 25,
                        type = "voxel"
                    )
                )
            }
        }
        "lock_crack" -> {
            repeat(burstLimit) {
                val ang = Random.nextFloat() * 2 * Math.PI.toFloat()
                val speed = 2f + Random.nextFloat() * 5f
                simulatedParticles.add(
                    LocalSimParticle(
                        id = Random.nextLong(),
                        x = 250f,
                        y = 160f,
                        vx = cos(ang) * speed,
                        vy = sin(ang) * speed,
                        color = Color(0xFF00E676),
                        size = 3f + Random.nextFloat() * 7f,
                        alpha = 1f,
                        maxLife = 35,
                        life = 35,
                        type = "matrix_fragment"
                    )
                )
            }
        }
    }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun VfxLibraryView(
    viewModel: GameViewModel,
    gameState: GameState
) {
    var searchQuery by remember { mutableStateOf("") }
    var selectedCategory by remember { mutableStateOf("ALL") }
    var selectedVfx by remember { mutableStateOf(vfxElementsList[0]) }
    
    // Configurable Sliders
    var particleCount by remember { mutableStateOf(80f) }
    var scaleFactor by remember { mutableStateOf(1.0f) }
    var selectedColorTheme by remember { mutableStateOf("Elemental/Energy") }
    var selectedBlendingMode by remember { mutableStateOf("ADD (Glow)") }
    var selectedQualityTier by remember { mutableStateOf("Enhanced") }
    
    var isPlaying by remember { mutableStateOf(true) }
    var isLooping by remember { mutableStateOf(true) }
    var activeTab by remember { mutableStateOf(0) } // 0 = GDScript, 1 = Inspector, 2 = Mobile Perf
    
    // Live Particle Simulator State
    val simulatedParticles = remember { mutableStateListOf<LocalSimParticle>() }
    var activeArcAngle by remember { mutableStateOf(0f) }
    var activeAoeRadius by remember { mutableStateOf(0f) }
    var scanLineY by remember { mutableStateOf(110f) }
    var scanDirection by remember { mutableStateOf(1f) }
    
    // Screen shake trigger animation
    var cameraShakeTime by remember { mutableStateOf(0) }
    
    // Categories matching the image
    val categories = listOf(
        "ALL", "01 COMBAT", "02 ABILITY", "03 MAGIC", 
        "04 ENV", "05 INTERACT", "06 UI", "07 STATUS", 
        "08 SUMMON", "09 IMPACT", "10 PORTAL", "11 WEATHER"
    )

    // Trigger local simulation loops
    LaunchedEffect(selectedVfx.id, isPlaying, isLooping) {
        var tick = 0
        var lastLightningTick = 0
        var lastSlashTick = 0
        var lastCrackTick = 0
        
        while (isPlaying) {
            delay(16) // ~60fps
            tick++
            
            // Camera shake timer decrement
            if (cameraShakeTime > 0) cameraShakeTime--
            
            // Update scanning animation
            scanLineY += 2f * scanDirection
            if (scanLineY >= 210f) {
                scanLineY = 210f
                scanDirection = -1f
            } else if (scanLineY <= 110f) {
                scanLineY = 110f
                scanDirection = 1f
            }
            
            // Update arc swipe animation
            activeArcAngle += 0.08f
            if (activeArcAngle > Math.PI.toFloat()) {
                activeArcAngle = 0f
            }
            
            // Update AoE expanding circle animation
            activeAoeRadius += 3f
            if (activeAoeRadius > 140f) {
                activeAoeRadius = 10f
            }
            
            // 1. Particle Physics and Decay
            val iterator = simulatedParticles.iterator()
            while (iterator.hasNext()) {
                val p = iterator.next()
                p.life -= 1
                if (p.life <= 0) {
                    iterator.remove()
                    continue
                }
                
                // Physics update
                p.x += p.vx
                p.y += p.vy
                
                // Category/behavior custom math
                when (selectedVfx.id) {
                    "fission_explosion" -> {
                        p.vx *= 0.94f
                        p.vy *= 0.94f
                    }
                    "event_horizon_portal" -> {
                        val cx = 250f
                        val cy = 160f
                        val dx = cx - p.x
                        val dy = cy - p.y
                        val dist = sqrt(dx*dx + dy*dy)
                        if (dist > 6f) {
                            p.vx += (dx / dist) * 0.35f
                            p.vy += (dy / dist) * 0.35f
                            val rx = -dy / dist
                            val ry = dx / dist
                            p.vx += rx * 1.8f
                            p.vy += ry * 1.8f
                        } else {
                            iterator.remove()
                            continue
                        }
                    }
                    "heal_pulse" -> {
                        p.vy = -1.8f
                        p.vx = sin(tick * 0.12f + p.id) * 2.5f
                    }
                    "neon_rain" -> {
                        p.vy += 0.15f
                        if (p.y >= 290f && p.vy > 0) {
                            p.y = 290f
                            p.vy = 0f
                            p.vx = 0f
                            p.type = "splash"
                            p.maxLife = 12
                            p.life = 12
                        }
                    }
                    "toxic_gas_vent" -> {
                        p.vx = sin(p.life * 0.04f + p.id) * 0.5f
                    }
                }
                p.alpha = p.life.toFloat() / p.maxLife.toFloat()
            }
            
            // 2. Loop Spawning
            if (isLooping) {
                val spawnCount = (particleCount * 0.12f).toInt().coerceAtLeast(1)
                when (selectedVfx.id) {
                    "neon_rain" -> {
                        repeat(spawnCount) {
                            simulatedParticles.add(
                                LocalSimParticle(
                                    id = Random.nextLong(),
                                    x = Random.nextFloat() * 500f,
                                    y = -10f,
                                    vx = -1.5f - Random.nextFloat() * 2f,
                                    vy = 10f + Random.nextFloat() * 5f,
                                    color = Color(0xFF00E5FF),
                                    size = 1f + Random.nextFloat() * 2f,
                                    alpha = 0.8f,
                                    maxLife = 60,
                                    life = 60,
                                    type = "rain"
                                )
                            )
                        }
                    }
                    "toxic_gas_vent" -> {
                        if (tick % 5 == 0) {
                            repeat(spawnCount) {
                                simulatedParticles.add(
                                    LocalSimParticle(
                                        id = Random.nextLong(),
                                        x = 250f + (Random.nextFloat() - 0.5f) * 45f,
                                        y = 290f,
                                        vx = (Random.nextFloat() - 0.5f) * 1.2f,
                                        vy = -1.2f - Random.nextFloat() * 1.5f,
                                        color = Color(0xFF00E676).copy(alpha = 0.35f),
                                        size = 16f + Random.nextFloat() * 18f,
                                        alpha = 0.45f,
                                        maxLife = 110,
                                        life = 110,
                                        type = "cloud"
                                    )
                                )
                            }
                        }
                    }
                    "event_horizon_portal" -> {
                        if (tick % 2 == 0) {
                            repeat(spawnCount) {
                                val ang = Random.nextFloat() * 2 * Math.PI.toFloat()
                                val R = 130f
                                simulatedParticles.add(
                                    LocalSimParticle(
                                        id = Random.nextLong(),
                                        x = 250f + cos(ang) * R,
                                        y = 160f + sin(ang) * R,
                                        vx = 0f,
                                        vy = 0f,
                                        color = Color(0xFFD500F9),
                                        size = 2f + Random.nextFloat() * 3f,
                                        alpha = 0.9f,
                                        maxLife = 90,
                                        life = 90,
                                        type = "dot"
                                    )
                                )
                            }
                        }
                    }
                    "heal_pulse" -> {
                        if (tick % 6 == 0) {
                            repeat(spawnCount) {
                                simulatedParticles.add(
                                    LocalSimParticle(
                                        id = Random.nextLong(),
                                        x = 250f + (Random.nextFloat() - 0.5f) * 35f,
                                        y = 210f,
                                        vx = 0f,
                                        vy = -1.5f,
                                        color = Color(0xFF00E676),
                                        size = 6f + Random.nextFloat() * 4f,
                                        alpha = 1.0f,
                                        maxLife = 55,
                                        life = 55,
                                        type = "cross"
                                    )
                                )
                            }
                        }
                    }
                }
                
                // Automatic interval timers for bursts
                if (selectedVfx.id == "melee_slash_arc" && tick - lastSlashTick > 50) {
                    lastSlashTick = tick
                    triggerVfxBurst("melee_slash_arc", simulatedParticles, particleCount)
                }
                if (selectedVfx.id == "plasma_ring_aoe" && tick % 80 == 0) {
                    triggerVfxBurst("plasma_ring_aoe", simulatedParticles, particleCount)
                }
                if (selectedVfx.id == "arcane_lightning" && tick - lastLightningTick > 90) {
                    lastLightningTick = tick
                    cameraShakeTime = 8
                    triggerVfxBurst("arcane_lightning", simulatedParticles, particleCount)
                }
                if (selectedVfx.id == "fission_explosion" && tick % 130 == 0) {
                    cameraShakeTime = 12
                    triggerVfxBurst("fission_explosion", simulatedParticles, particleCount)
                }
                if (selectedVfx.id == "level_up_wings" && tick % 100 == 0) {
                    triggerVfxBurst("level_up_wings", simulatedParticles, particleCount)
                }
                if (selectedVfx.id == "cyber_assembler" && tick % 80 == 0) {
                    triggerVfxBurst("cyber_assembler", simulatedParticles, particleCount)
                }
                if (selectedVfx.id == "lock_crack" && tick - lastCrackTick > 90) {
                    lastCrackTick = tick
                    triggerVfxBurst("lock_crack", simulatedParticles, particleCount)
                }
            }
        }
    }

    // Dynamic color override mapping based on sliders
    val colorOverride = when (selectedColorTheme) {
        "Elemental/Energy" -> when (selectedVfx.id) {
            "melee_slash_arc", "plasma_ring_aoe", "fission_explosion" -> VfxOrange
            "arcane_lightning", "neon_rain" -> VfxCyan
            "heal_pulse", "lock_crack" -> VfxGreen
            else -> VfxPurple
        }
        "Neutral/Physical" -> VfxGold
        else -> VfxPurple
    }

    // Filtered VFX elements list
    val filteredVfxList = vfxElementsList.filter {
        (selectedCategory == "ALL" || it.category.contains(selectedCategory.substring(3))) &&
        (searchQuery.isEmpty() || it.name.contains(searchQuery, ignoreCase = true) || it.description.contains(searchQuery, ignoreCase = true))
    }

    Row(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF07090E))
            .padding(12.dp),
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        
        // ==========================================
        // LEFT COL: VFX LIBRARY SELECTOR (1/3 Width)
        // ==========================================
        Column(
            modifier = Modifier
                .weight(1.1f)
                .fillMaxHeight(),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            
            // Header panel matching "QUANTUM EFFECT FX & VFX LIBRARY"
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.Black.copy(alpha = 0.5f)),
                border = BorderStroke(1.dp, VfxBorder)
            ) {
                Column(modifier = Modifier.padding(12.dp)) {
                    Text(
                        text = "QUANTUM EFFECT",
                        color = VfxPurple,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace
                    )
                    Text(
                        text = "FX & VFX BIBLE",
                        color = Color.White,
                        fontSize = 18.sp,
                        fontWeight = FontWeight.ExtraBold,
                        fontFamily = FontFamily.SansSerif
                    )
                    Text(
                        text = "Visual language for a living, reactive cyberpunk world.",
                        color = QuantumGrayText,
                        fontSize = 9.sp,
                        fontFamily = FontFamily.SansSerif,
                        modifier = Modifier.padding(top = 2.dp)
                    )
                }
            }

            // Category Chips Row (Horizontal Scrollable Filter)
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .horizontalScroll(rememberScrollState())
                    .background(Color.Black.copy(alpha = 0.2f), RoundedCornerShape(6.dp))
                    .padding(4.dp),
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                categories.forEach { cat ->
                    val isSelected = selectedCategory == cat
                    Box(
                        modifier = Modifier
                            .clickable { selectedCategory = cat }
                            .background(
                                if (isSelected) VfxPurple.copy(alpha = 0.2f) else Color.Transparent,
                                RoundedCornerShape(4.dp)
                            )
                            .border(
                                0.5.dp,
                                if (isSelected) VfxPurple else Color.Transparent,
                                RoundedCornerShape(4.dp)
                            )
                            .padding(horizontal = 8.dp, vertical = 4.dp)
                    ) {
                        Text(
                            text = cat,
                            color = if (isSelected) Color.White else QuantumGrayText,
                            fontSize = 8.sp,
                            fontWeight = FontWeight.Bold,
                            fontFamily = FontFamily.Monospace
                        )
                    }
                }
            }

            // Search input field
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                modifier = Modifier.fillMaxWidth().testTag("vfx_search_input"),
                textStyle = MaterialTheme.typography.bodySmall.copy(color = Color.White),
                placeholder = { Text("Search visual effects...", color = QuantumGrayText, fontSize = 10.sp) },
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = VfxPurple,
                    unfocusedBorderColor = VfxBorder,
                    focusedContainerColor = Color(0xFF0C1017),
                    unfocusedContainerColor = Color(0xFF07090D)
                ),
                shape = RoundedCornerShape(6.dp)
            )

            // Scrollable List of filtered VFX
            Box(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .background(Color.Black.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                    .border(0.5.dp, VfxBorder, RoundedCornerShape(8.dp))
                    .padding(4.dp)
            ) {
                LazyColumn(
                    verticalArrangement = Arrangement.spacedBy(6.dp),
                    modifier = Modifier.fillMaxSize()
                ) {
                    items(filteredVfxList) { vfx ->
                        val isSelected = selectedVfx.id == vfx.id
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    selectedVfx = vfx
                                    simulatedParticles.clear()
                                },
                            colors = CardDefaults.cardColors(
                                containerColor = if (isSelected) VfxPurple.copy(alpha = 0.15f) else Color(0xFF0F141F)
                            ),
                            border = BorderStroke(
                                if (isSelected) 1.dp else 0.5.dp,
                                if (isSelected) VfxPurple else VfxBorder.copy(alpha = 0.4f)
                            )
                        ) {
                            Column(modifier = Modifier.padding(10.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = vfx.category,
                                        color = VfxPurple,
                                        fontSize = 8.sp,
                                        fontWeight = FontWeight.Bold,
                                        fontFamily = FontFamily.Monospace
                                    )
                                    
                                    // Cost Indicator badge
                                    val costBadgeColor = when (vfx.performanceCost) {
                                        "Low Cost" -> VfxGreen
                                        "Medium Cost" -> VfxGold
                                        else -> VfxRed
                                    }
                                    Text(
                                        text = vfx.performanceCost.uppercase(),
                                        color = costBadgeColor,
                                        fontSize = 7.5.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        fontFamily = FontFamily.Monospace
                                    )
                                }
                                
                                Text(
                                    text = vfx.name,
                                    color = Color.White,
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    fontFamily = FontFamily.SansSerif,
                                    modifier = Modifier.padding(vertical = 1.dp)
                                )
                                
                                Text(
                                    text = vfx.description,
                                    color = QuantumGrayText,
                                    fontSize = 8.5.sp,
                                    maxLines = 2,
                                    fontFamily = FontFamily.SansSerif,
                                    lineHeight = 11.sp
                                )

                                Spacer(modifier = Modifier.height(4.dp))
                                
                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    // Quality Tier Badge
                                    Box(
                                        modifier = Modifier
                                            .background(VfxBorder.copy(alpha = 0.3f), RoundedCornerShape(2.dp))
                                            .padding(horizontal = 4.dp, vertical = 1.dp)
                                    ) {
                                        Text(
                                            text = "TIER: ${vfx.defaultTier.uppercase()}",
                                            color = Color.White,
                                            fontSize = 7.sp,
                                            fontWeight = FontWeight.Bold,
                                            fontFamily = FontFamily.Monospace
                                        )
                                    }
                                    
                                    // Blend Mode badge
                                    Box(
                                        modifier = Modifier
                                            .background(VfxBorder.copy(alpha = 0.3f), RoundedCornerShape(2.dp))
                                            .padding(horizontal = 4.dp, vertical = 1.dp)
                                    ) {
                                        Text(
                                            text = vfx.blendingMode,
                                            color = VfxCyan,
                                            fontSize = 7.sp,
                                            fontWeight = FontWeight.Bold,
                                            fontFamily = FontFamily.Monospace
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // =======================================================
        // RIGHT COL: SIMULATOR & PRODUCTION EXPORTER (2/3 Width)
        // =======================================================
        Column(
            modifier = Modifier
                .weight(2f)
                .fillMaxHeight(),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            
            // 1. Real-time Holographic Simulation Chamber
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(290.dp),
                colors = CardDefaults.cardColors(containerColor = VfxDarkBg),
                border = BorderStroke(1.dp, VfxBorder)
            ) {
                Column(modifier = Modifier.fillMaxSize()) {
                    
                    // Header of Chamber
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.Black.copy(alpha = 0.4f))
                            .padding(horizontal = 12.dp, vertical = 6.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            // Pulsating red record dot
                            Box(
                                modifier = Modifier
                                    .size(6.dp)
                                    .background(if (isPlaying) VfxRed else Color.Gray, CircleShape)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = "⚡ QUANTUM CHAMBER SIMULATOR",
                                color = VfxCyan,
                                fontSize = 9.sp,
                                fontWeight = FontWeight.Bold,
                                fontFamily = FontFamily.Monospace
                            )
                        }
                        
                        Text(
                            text = "SELECTED: ${selectedVfx.name.uppercase()}",
                            color = Color.White,
                            fontSize = 8.5.sp,
                            fontWeight = FontWeight.Bold,
                            fontFamily = FontFamily.Monospace
                        )
                    }

                    // Interactive Canvas
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .weight(1f)
                            .background(Color(0xFF05070B))
                    ) {
                        
                        // Shake the canvas based on active camera shaking timer
                        val dxShake = if (cameraShakeTime > 0) Random.nextFloat() * 12f - 6f else 0f
                        val dyShake = if (cameraShakeTime > 0) Random.nextFloat() * 12f - 6f else 0f
                        
                        Canvas(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(8.dp)
                                .offset { IntOffset(dxShake.roundToInt(), dyShake.roundToInt()) }
                        ) {
                            val w = size.width
                            val h = size.height
                            val cx = w / 2f
                            val cy = h / 2f
                            
                            // Draw Cybernetic Gridlines
                            val gridSpacing = 30f
                            var xGrid = 0f
                            while (xGrid < w) {
                                drawLine(
                                    color = VfxGridColor.copy(alpha = 0.3f),
                                    start = Offset(xGrid, 0f),
                                    end = Offset(xGrid, h),
                                    strokeWidth = 0.5f
                                )
                                xGrid += gridSpacing
                            }
                            var yGrid = 0f
                            while (yGrid < h) {
                                drawLine(
                                    color = VfxGridColor.copy(alpha = 0.3f),
                                    start = Offset(0f, yGrid),
                                    end = Offset(w, yGrid),
                                    strokeWidth = 0.5f
                                )
                                yGrid += gridSpacing
                            }
                            
                            // Floor grid boundaries
                            drawLine(
                                color = VfxBorder.copy(alpha = 0.4f),
                                start = Offset(0f, 290f),
                                end = Offset(w, 290f),
                                strokeWidth = 1.5f
                            )

                            // DRAW CENTRAL ANCHOR DRONE (Cyber Companion Anchor)
                            if (selectedVfx.id != "neon_rain") {
                                // Shadow on floor
                                drawOval(
                                    color = Color.Black.copy(alpha = 0.4f),
                                    topLeft = Offset(cx - 20f, 280f),
                                    size = Size(40f, 10f)
                                )
                                
                                // Floating center drone
                                drawCircle(
                                    brush = Brush.radialGradient(
                                        colors = listOf(Color.White, colorOverride.copy(alpha = 0.8f))
                                    ),
                                    radius = 12f * scaleFactor,
                                    center = Offset(cx, 160f)
                                )
                                drawCircle(
                                    color = colorOverride,
                                    radius = 16f * scaleFactor,
                                    center = Offset(cx, 160f),
                                    style = Stroke(width = 1.5f)
                                )
                                // Wing appendages
                                drawLine(
                                    color = colorOverride,
                                    start = Offset(cx - 30f * scaleFactor, 160f),
                                    end = Offset(cx - 15f * scaleFactor, 160f),
                                    strokeWidth = 2f
                                )
                                drawLine(
                                    color = colorOverride,
                                    start = Offset(cx + 15f * scaleFactor, 160f),
                                    end = Offset(cx + 30f * scaleFactor, 160f),
                                    strokeWidth = 2f
                                )
                            }

                            // PROCEDURAL OVERLAY VECTOR ELEMENTS
                            when (selectedVfx.id) {
                                "melee_slash_arc" -> {
                                    // Sweeping slash trail path
                                    val path = Path()
                                    val sweepR = 75f * scaleFactor
                                    var isFirst = true
                                    for (deg in 0..180) {
                                        val rad = Math.toRadians(deg.toDouble()).toFloat()
                                        if (rad <= activeArcAngle) {
                                            val px = cx + cos(rad - Math.PI.toFloat()/4) * sweepR
                                            val py = 160f + sin(rad - Math.PI.toFloat()/4) * sweepR
                                            if (isFirst) {
                                                path.moveTo(px, py)
                                                isFirst = false
                                            } else {
                                                path.lineTo(px, py)
                                            }
                                        }
                                    }
                                    drawPath(
                                        path = path,
                                        color = colorOverride.copy(alpha = 0.5f),
                                        style = Stroke(width = 8f * scaleFactor)
                                    )
                                    drawPath(
                                        path = path,
                                        color = Color.White,
                                        style = Stroke(width = 3f * scaleFactor)
                                    )
                                }
                                "plasma_ring_aoe" -> {
                                    // Expanding concentric neon circular blast lines
                                    drawCircle(
                                        color = colorOverride.copy(alpha = (1.0f - activeAoeRadius / 140f).coerceIn(0f, 1f)),
                                        radius = activeAoeRadius * scaleFactor,
                                        center = Offset(cx, 160f),
                                        style = Stroke(width = 4f)
                                    )
                                    drawCircle(
                                        color = colorOverride.copy(alpha = ((1.0f - (activeAoeRadius + 40f) % 140f / 140f)).coerceIn(0f, 1f)),
                                        radius = ((activeAoeRadius + 40f) % 140f) * scaleFactor,
                                        center = Offset(cx, 160f),
                                        style = Stroke(width = 2f)
                                    )
                                }
                                "arcane_lightning" -> {
                                    // Sky flash
                                    if (cameraShakeTime > 4) {
                                        drawRect(
                                            color = Color.White.copy(alpha = 0.2f),
                                            topLeft = Offset.Zero,
                                            size = size
                                        )
                                    }
                                    
                                    // Jagged vector lightning strike path
                                    if (cameraShakeTime > 0) {
                                        val path = Path()
                                        path.moveTo(cx - 30f, 0f)
                                        path.lineTo(cx + 20f, 70f)
                                        path.lineTo(cx - 15f, 140f)
                                        path.lineTo(cx + 35f, 210f)
                                        path.lineTo(cx, 290f)
                                        
                                        drawPath(
                                            path = path,
                                            color = colorOverride.copy(alpha = 0.4f),
                                            style = Stroke(width = 12f * scaleFactor)
                                        )
                                        drawPath(
                                            path = path,
                                            color = Color.White,
                                            style = Stroke(width = 4f * scaleFactor)
                                        )
                                    }
                                }
                                "lock_crack" -> {
                                    // Floating geometric matrix shield lock
                                    val shieldR = 36f * scaleFactor
                                    drawCircle(
                                        color = colorOverride.copy(alpha = 0.3f),
                                        radius = shieldR,
                                        center = Offset(cx, 160f),
                                        style = Stroke(width = 2f)
                                    )
                                    // Render geometric ribs
                                    repeat(6) { index ->
                                        val ang = (index * Math.PI / 3).toFloat()
                                        drawLine(
                                            color = colorOverride.copy(alpha = 0.4f),
                                            start = Offset(cx, 160f),
                                            end = Offset(cx + cos(ang) * shieldR, 160f + sin(ang) * shieldR),
                                            strokeWidth = 1f
                                        )
                                    }
                                }
                                "cyber_assembler" -> {
                                    // Hovering laser sweep bar
                                    drawLine(
                                        color = colorOverride.copy(alpha = 0.8f),
                                        start = Offset(cx - 60f * scaleFactor, scanLineY),
                                        end = Offset(cx + 60f * scaleFactor, scanLineY),
                                        strokeWidth = 2f
                                    )
                                    
                                    // Scan glow shader band
                                    drawRect(
                                        color = colorOverride.copy(alpha = 0.12f),
                                        topLeft = Offset(cx - 60f * scaleFactor, scanLineY - 15f),
                                        size = Size(120f * scaleFactor, 30f)
                                    )
                                }
                                "event_horizon_portal" -> {
                                    // Gravitational black hole core
                                    drawCircle(
                                        color = Color.Black,
                                        radius = 24f * scaleFactor,
                                        center = Offset(cx, 160f)
                                    )
                                    drawCircle(
                                        color = colorOverride.copy(alpha = 0.6f),
                                        radius = 28f * scaleFactor,
                                        center = Offset(cx, 160f),
                                        style = Stroke(width = 3f)
                                    )
                                    drawCircle(
                                        color = colorOverride.copy(alpha = 0.3f),
                                        radius = 40f * scaleFactor,
                                        center = Offset(cx, 160f),
                                        style = Stroke(width = 1.5f)
                                    )
                                }
                            }

                            // DRAW ALL SIMULATED ACTIVE PARTICLES
                            simulatedParticles.forEach { p ->
                                val finalColor = if (selectedColorTheme == "Elemental/Energy") p.color else colorOverride
                                when (p.type) {
                                    "rain" -> {
                                        drawLine(
                                            color = finalColor.copy(alpha = p.alpha),
                                            start = Offset(p.x, p.y),
                                            end = Offset(p.x - 3f, p.y + 12f),
                                            strokeWidth = p.size
                                        )
                                    }
                                    "splash" -> {
                                        drawCircle(
                                            color = finalColor.copy(alpha = p.alpha),
                                            radius = (12f - p.life) * 1.5f * scaleFactor,
                                            center = Offset(p.x, p.y),
                                            style = Stroke(width = 1f)
                                        )
                                    }
                                    "cloud" -> {
                                        drawCircle(
                                            color = finalColor.copy(alpha = p.alpha * 0.18f),
                                            radius = p.size * scaleFactor,
                                            center = Offset(p.x, p.y)
                                        )
                                    }
                                    "cross" -> {
                                        // Green medical nanite crosses
                                        val cs = p.size * scaleFactor
                                        drawLine(
                                            color = finalColor.copy(alpha = p.alpha),
                                            start = Offset(p.x - cs, p.y),
                                            end = Offset(p.x + cs, p.y),
                                            strokeWidth = 2f
                                        )
                                        drawLine(
                                            color = finalColor.copy(alpha = p.alpha),
                                            start = Offset(p.x, p.y - cs),
                                            end = Offset(p.x, p.y + cs),
                                            strokeWidth = 2f
                                        )
                                    }
                                    "wing" -> {
                                        // Radiant diagonal feathery particles
                                        drawCircle(
                                            color = finalColor.copy(alpha = p.alpha),
                                            radius = p.size * 0.8f * scaleFactor,
                                            center = Offset(p.x, p.y)
                                        )
                                    }
                                    "spark" -> {
                                        // Stretch line spark in movement direction
                                        val velLen = sqrt(p.vx * p.vx + p.vy * p.vy)
                                        if (velLen > 0.1f) {
                                            val dxNorm = p.vx / velLen
                                            val dyNorm = p.vy / velLen
                                            drawLine(
                                                color = finalColor.copy(alpha = p.alpha),
                                                start = Offset(p.x, p.y),
                                                end = Offset(p.x - dxNorm * 10f, p.y - dyNorm * 10f),
                                                strokeWidth = 1.5f
                                            )
                                        }
                                    }
                                    else -> {
                                        // Standard dots or circular embers
                                        drawCircle(
                                            color = finalColor.copy(alpha = p.alpha),
                                            radius = p.size * scaleFactor,
                                            center = Offset(p.x, p.y)
                                        )
                                    }
                                }
                            }
                        }
                    }

                    // Bottom Player Controls Row
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.Black.copy(alpha = 0.5f))
                            .padding(8.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            CyberButton(
                                onClick = { isPlaying = !isPlaying },
                                text = if (isPlaying) "⏸️ PAUSE" else "▶️ PLAY",
                                color = if (isPlaying) VfxGold else VfxGreen,
                                modifier = Modifier.wrapContentWidth().testTag("vfx_play_pause_button")
                            )

                            CyberButton(
                                onClick = {
                                    triggerVfxBurst(selectedVfx.id, simulatedParticles, particleCount)
                                    if (selectedVfx.id == "arcane_lightning") cameraShakeTime = 8
                                    if (selectedVfx.id == "fission_explosion") cameraShakeTime = 12
                                },
                                text = "💥 TRIGGER BURST",
                                color = VfxRed,
                                modifier = Modifier.wrapContentWidth().testTag("vfx_trigger_burst_button")
                            )
                        }

                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Text("LOOP", color = QuantumGrayText, fontSize = 8.sp, fontWeight = FontWeight.Bold)
                            Switch(
                                checked = isLooping,
                                onCheckedChange = { isLooping = it },
                                modifier = Modifier.testTag("vfx_loop_switch"),
                                colors = SwitchDefaults.colors(
                                    checkedThumbColor = VfxPurple,
                                    checkedTrackColor = VfxPurple.copy(alpha = 0.3f),
                                    uncheckedThumbColor = Color.Gray,
                                    uncheckedTrackColor = Color.Black
                                )
                            )
                        }
                    }
                }
            }

            // 2. Control Customization Panel
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color(0xFF0F1219)),
                border = BorderStroke(1.dp, VfxBorder)
            ) {
                Column(modifier = Modifier.padding(10.dp)) {
                    Text(
                        text = "🛠️ SIMULATION THROTTLE & CALIBRATION",
                        color = VfxPurple,
                        fontSize = 9.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace
                    )
                    
                    Spacer(modifier = Modifier.height(8.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        // Slider Left
                        Column(modifier = Modifier.weight(1f)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text("PARTICLE COUNT: ${particleCount.toInt()}", color = Color.White, fontSize = 9.sp, fontFamily = FontFamily.Monospace)
                                Text(
                                    text = if (particleCount > 130) "🔴 STRESS TEST" else if (particleCount > 70) "🟡 MEDIUM LOAD" else "🟢 OPTIMAL",
                                    color = if (particleCount > 130) VfxRed else if (particleCount > 70) VfxGold else VfxGreen,
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                            Slider(
                                value = particleCount,
                                onValueChange = { particleCount = it },
                                valueRange = 10f..200f,
                                modifier = Modifier.testTag("vfx_particle_count_slider"),
                                colors = SliderDefaults.colors(thumbColor = VfxPurple, activeTrackColor = VfxPurple)
                            )
                        }

                        // Slider Right
                        Column(modifier = Modifier.weight(1f)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text("SCALE FACTOR: ${String.format(java.util.Locale.US, "%.1fx", scaleFactor)}", color = Color.White, fontSize = 9.sp, fontFamily = FontFamily.Monospace)
                                Text("IN-GAME SIZE", color = QuantumGrayText, fontSize = 8.sp)
                            }
                            Slider(
                                value = scaleFactor,
                                onValueChange = { scaleFactor = it },
                                valueRange = 0.5f..2.0f,
                                modifier = Modifier.testTag("vfx_scale_factor_slider"),
                                colors = SliderDefaults.colors(thumbColor = VfxCyan, activeTrackColor = VfxCyan)
                            )
                        }
                    }

                    // Bottom customization chips
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // Color Theme Selection
                        Column(modifier = Modifier.weight(1f)) {
                            Text("COLOR RE-MAPPING", color = QuantumGrayText, fontSize = 8.sp, fontWeight = FontWeight.Bold)
                            Row(horizontalArrangement = Arrangement.spacedBy(4.dp), modifier = Modifier.padding(top = 4.dp)) {
                                listOf("Elemental/Energy", "Neutral/Physical", "Special/Exotic").forEach { theme ->
                                    val isSelected = selectedColorTheme == theme
                                    Box(
                                        modifier = Modifier
                                            .clickable { selectedColorTheme = theme }
                                            .background(
                                                if (isSelected) VfxPurple.copy(alpha = 0.2f) else Color.Transparent,
                                                RoundedCornerShape(4.dp)
                                            )
                                            .border(
                                                0.5.dp,
                                                if (isSelected) VfxPurple else VfxBorder.copy(alpha = 0.3f),
                                                RoundedCornerShape(4.dp)
                                            )
                                            .padding(horizontal = 6.dp, vertical = 4.dp)
                                    ) {
                                        Text(
                                            text = theme.substringBefore("/").uppercase(),
                                            color = if (isSelected) Color.White else QuantumGrayText,
                                            fontSize = 7.5.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        }

                        // Quality Tier Selector
                        Column(modifier = Modifier.weight(1f)) {
                            Text("VFX QUALITY OPTIMIZATION TIER", color = QuantumGrayText, fontSize = 8.sp, fontWeight = FontWeight.Bold)
                            Row(horizontalArrangement = Arrangement.spacedBy(4.dp), modifier = Modifier.padding(top = 4.dp)) {
                                listOf("Basic", "Enhanced", "Premium").forEach { tier ->
                                    val isSelected = selectedQualityTier == tier
                                    Box(
                                        modifier = Modifier
                                            .clickable { selectedQualityTier = tier }
                                            .background(
                                                if (isSelected) VfxCyan.copy(alpha = 0.2f) else Color.Transparent,
                                                RoundedCornerShape(4.dp)
                                            )
                                            .border(
                                                0.5.dp,
                                                if (isSelected) VfxCyan else VfxBorder.copy(alpha = 0.3f),
                                                RoundedCornerShape(4.dp)
                                            )
                                            .padding(horizontal = 6.dp, vertical = 4.dp)
                                    ) {
                                        Text(
                                            text = tier.uppercase(),
                                            color = if (isSelected) Color.White else QuantumGrayText,
                                            fontSize = 7.5.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // 3. Tabbed Production Composable Exporter and Setup
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                colors = CardDefaults.cardColors(containerColor = Color.Black.copy(alpha = 0.6f)),
                border = BorderStroke(1.dp, VfxBorder)
            ) {
                Column(modifier = Modifier.padding(10.dp)) {
                    // Exporter Tabs
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.Black.copy(alpha = 0.3f), RoundedCornerShape(6.dp))
                            .padding(2.dp),
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        val tabs = listOf("⚡ COMPOSE ENGINE", "📋 COMPOSE SETUP", "📱 MOBILE PERFORMANCE", "🖼️ COMBAT VFX SHEET")
                        tabs.forEachIndexed { idx, label ->
                            val isSelected = activeTab == idx
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clickable { activeTab = idx }
                                    .background(
                                        if (isSelected) VfxPurple.copy(alpha = 0.25f) else Color.Transparent,
                                        RoundedCornerShape(4.dp)
                                    )
                                    .padding(vertical = 6.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = label,
                                    color = if (isSelected) Color.White else QuantumGrayText,
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.Bold,
                                    fontFamily = FontFamily.Monospace
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    // Content views for tabs
                    when (activeTab) {
                        0 -> {
                            // Dynamic GDScript editor with copyable instructions
                            Column(modifier = Modifier.fillMaxSize()) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = "ANDROID COMPOSE READY KOTLIN ENGINE (SLIDERS SYNCHRONIZED)",
                                        color = VfxPurple,
                                        fontSize = 8.sp,
                                        fontWeight = FontWeight.Bold,
                                        fontFamily = FontFamily.Monospace
                                    )
                                    
                                    Box(
                                        modifier = Modifier
                                            .background(VfxGreen.copy(alpha = 0.15f), RoundedCornerShape(3.dp))
                                            .padding(horizontal = 4.dp, vertical = 2.dp)
                                    ) {
                                        Text(
                                            text = "HIGH-END MOBILE OPTIMIZED",
                                            color = VfxGreen,
                                            fontSize = 7.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                                
                                Spacer(modifier = Modifier.height(4.dp))
                                
                                // Scrollable Code Block
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .weight(1f)
                                        .background(Color(0xFF07090E), RoundedCornerShape(6.dp))
                                        .border(0.5.dp, Color(0xFF1B2330), RoundedCornerShape(6.dp))
                                        .verticalScroll(rememberScrollState())
                                        .padding(8.dp)
                                ) {
                                    Text(
                                        text = getDynamicGdScript(selectedVfx, scaleFactor, particleCount.toInt()),
                                        color = Color(0xFFCE9178), // code syntax coloring
                                        fontSize = 8.sp,
                                        fontFamily = FontFamily.Monospace,
                                        lineHeight = 11.sp
                                    )
                                }
                            }
                        }
                        
                        1 -> {
                            // Inspector Setup Instructions for non-coders
                            Column(modifier = Modifier.fillMaxSize()) {
                                Text(
                                    text = "STEP-BY-STEP JETPACK COMPOSE INTEGRATION (NO CODE REQUIRED)",
                                    color = VfxGold,
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.Bold,
                                    fontFamily = FontFamily.Monospace
                                )
                                Spacer(modifier = Modifier.height(6.dp))
                                
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .weight(1f)
                                        .background(Color(0xFF07090E), RoundedCornerShape(6.dp))
                                        .border(0.5.dp, Color(0xFF1B2330), RoundedCornerShape(6.dp))
                                        .verticalScroll(rememberScrollState())
                                        .padding(8.dp)
                                ) {
                                    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                        Text(
                                            text = "Primary Compose Component: ${getComposeComponentForNode(selectedVfx.godotNode)}",
                                            color = Color.White,
                                            fontSize = 9.sp,
                                            fontWeight = FontWeight.Bold,
                                            fontFamily = FontFamily.Monospace
                                        )
                                        
                                        HorizontalDivider(color = VfxBorder.copy(alpha = 0.3f))
                                        
                                        Text(
                                            text = "Critical Composable Modifiers to Configure:",
                                            color = VfxCyan,
                                            fontSize = 8.5.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                        
                                        selectedVfx.inspectorProperties.forEach { prop ->
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text(text = " • ${prop.first}", color = QuantumGrayText, fontSize = 8.sp, fontFamily = FontFamily.Monospace)
                                                Text(text = "➞  ${prop.second}", color = Color.White, fontSize = 8.sp, fontFamily = FontFamily.Monospace)
                                            }
                                        }
                                        
                                        HorizontalDivider(color = VfxBorder.copy(alpha = 0.3f))
                                        
                                        Text(
                                            text = "Android Implementation Steps:",
                                            color = VfxPurple,
                                            fontSize = 8.5.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                        
                                        Text(
                                            text = getDynamicSetupInstructions(selectedVfx, scaleFactor, particleCount.toInt()),
                                            color = Color.White,
                                            fontSize = 8.sp,
                                            lineHeight = 11.sp,
                                            fontFamily = FontFamily.SansSerif
                                        )
                                    }
                                }
                            }
                        }
                        
                        2 -> {
                            // Mobile performance recommendations (OnePlus 15, Samsung Fold 6)
                            Column(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .verticalScroll(rememberScrollState()),
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = "HIGH-PERFORMANCE TARGET CHASSIS CALIBRATION",
                                        color = VfxCyan,
                                        fontSize = 8.5.sp,
                                        fontWeight = FontWeight.Bold,
                                        fontFamily = FontFamily.Monospace
                                    )
                                    
                                    Box(
                                        modifier = Modifier
                                            .background(VfxGold.copy(alpha = 0.15f), RoundedCornerShape(3.dp))
                                            .padding(horizontal = 5.dp, vertical = 2.dp)
                                    ) {
                                        Text(
                                            text = "60 FPS GUARANTEE",
                                            color = VfxGold,
                                            fontSize = 7.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                                
                                HorizontalDivider(color = VfxBorder.copy(alpha = 0.3f))
                                
                                Text(
                                    text = "Target Hardware: Samsung Galaxy Z Fold 6 / OnePlus 15 Pro",
                                    color = Color.White,
                                    fontSize = 9.sp,
                                    fontWeight = FontWeight.Bold
                                )
                                
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    Card(
                                        modifier = Modifier.weight(1f),
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFF141722)),
                                        border = BorderStroke(0.5.dp, VfxGreen.copy(alpha = 0.3f))
                                    ) {
                                        Column(modifier = Modifier.padding(6.dp)) {
                                            Text("🟢 BASIC TIER ADVICE", color = VfxGreen, fontSize = 7.5.sp, fontWeight = FontWeight.Bold)
                                            Text(
                                                text = "Uses CPUParticles2D. Safe for low-end companions. Runs entirely on CPU thread. No batching overhead.",
                                                color = QuantumGrayText,
                                                fontSize = 7.5.sp,
                                                lineHeight = 10.sp
                                            )
                                        }
                                    }

                                    Card(
                                        modifier = Modifier.weight(1f),
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFF141722)),
                                        border = BorderStroke(0.5.dp, VfxGold.copy(alpha = 0.3f))
                                    ) {
                                        Column(modifier = Modifier.padding(6.dp)) {
                                            Text("🟡 ENHANCED TIER ADVICE", color = VfxGold, fontSize = 7.5.sp, fontWeight = FontWeight.Bold)
                                            Text(
                                                text = "Uses GPUParticles2D. Implements dynamic material instances. Supports GPU caching. Limit to 3 active systems simultaneously.",
                                                color = QuantumGrayText,
                                                fontSize = 7.5.sp,
                                                lineHeight = 10.sp
                                            )
                                        }
                                    }

                                    Card(
                                        modifier = Modifier.weight(1f),
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFF141722)),
                                        border = BorderStroke(0.5.dp, VfxRed.copy(alpha = 0.3f))
                                    ) {
                                        Column(modifier = Modifier.padding(6.dp)) {
                                            Text("🔴 PREMIUM TIER ADVICE", color = VfxRed, fontSize = 7.5.sp, fontWeight = FontWeight.Bold)
                                            Text(
                                                text = "Requires dedicated custom GLES3 shader materials. Uses camera viewport-shake matrices. Cull beyond 400 pixels distance.",
                                                color = QuantumGrayText,
                                                fontSize = 7.5.sp,
                                                lineHeight = 10.sp
                                            )
                                        }
                                    }
                                }
                                
                                HorizontalDivider(color = VfxBorder.copy(alpha = 0.3f))
                                
                                Text(
                                    text = "💡 LEAD DEV MOBILE OPTIMIZATION TRICKS:",
                                    color = VfxPurple,
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.Bold,
                                    fontFamily = FontFamily.Monospace
                                )
                                Text(
                                    text = "1. DISABLE particle collision on small glowing embers. Use radial curves instead.\n" +
                                           "2. ENABLE 'Use GPU Batching' in Project Settings -> Rendering -> 2D.\n" +
                                           "3. PRE-ALLOCATE particle pools on level loads. Do not instantiate/free GPUParticles2D nodes dynamically during active bullet-hell segments.\n" +
                                           "4. COUPLING BLEND MODES: Use 'Add' blend mode sparingly. Multiplying 'Add' blends over complex translucent backgrounds causes overdraw pixel-fill rate drops on Mali/Adreno GPUs.",
                                    color = Color.White,
                                    fontSize = 7.5.sp,
                                    lineHeight = 10.sp,
                                    fontFamily = FontFamily.SansSerif
                                )
                            }
                        }
                        
                        3 -> {
                            VfxReferenceSheetTab(
                                selectedVfx = selectedVfx,
                                onSelectVfx = {
                                    selectedVfx = it
                                    simulatedParticles.clear()
                                }
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun VfxReferenceSheetTab(
    selectedVfx: VfxElement,
    onSelectVfx: (VfxElement) -> Unit
) {
    var selectedCategoryIndex by remember { mutableStateOf(0) }
    
    val categoryDetails = remember {
        listOf(
            CategoryDetail(
                title = "Melee & Physical Effects",
                emoji = "🗡️",
                description = "High-velocity blade sweeps, crushing ground impacts, and physical kinetic impacts. Standard frame rate is 8-12 FPS with strong directional motion blur.",
                combatVfxIds = listOf("melee_slash_arc"),
                godotTip = "Tip: Use Compose Custom Canvas with Path and DrawScope.drawPath to render smooth, high-fidelity neon sweep trails."
            ),
            CategoryDetail(
                title = "Ranged & Projectile Effects",
                emoji = "🏹",
                description = "Homing energy bolts, piercing sniper rails, and projectile trail particles. Built with extreme speed scales and additive glows.",
                combatVfxIds = listOf("plasma_ring_aoe", "arcane_lightning"),
                godotTip = "Tip: Use rememberUpdatedState to track active targets on background coroutine frames while drawing projectiles."
            ),
            CategoryDetail(
                title = "Energy & Tech Effects",
                emoji = "⚡",
                description = "Force fields, gravitational wells, and EMP blasts. Styled with neon-purple and cyan geometric meshes, ring curves, and digitized grids.",
                combatVfxIds = listOf("plasma_ring_aoe", "cybermatic_assembler"),
                godotTip = "Tip: Combine DrawScope.drawCircle radial gradient brushes with BlendMode.Screen for vibrant, glowing holographic rings."
            ),
            CategoryDetail(
                title = "Magic & Elemental Effects",
                emoji = "🔥",
                description = "Raging firestorms, crackling thunderbolts, and localized ice storms. Employs dynamic heat-distortion shaders and complex particle color ramps.",
                combatVfxIds = listOf("arcane_lightning", "neon_rain", "fission_explosion"),
                godotTip = "Tip: Apply dynamic color transitions using animateColorAsState to interpolate particles from hot core white to neon orange/magenta."
            ),
            CategoryDetail(
                title = "Status & Debuff Effects",
                emoji = "💀",
                description = "Corrosive neon toxic gas, burning nano-fires, freezing ice halos, and slow-motion field bubbles. Emitted in low-velocity circular patterns.",
                combatVfxIds = listOf("gas_vent", "neon_rain"),
                godotTip = "Tip: Linearly scale down particle size and decrease alpha to simulate fading, dissolving or dispersing fields."
            ),
            CategoryDetail(
                title = "Heal & Support Effects",
                emoji = "❇️",
                description = "Nanite healing pulses, digital shields, speed boosts, and revivals. Styled with soft emerald green and golden sparkles and upward-drifting cross symbols.",
                combatVfxIds = listOf("heal_pulse", "cybermatic_assembler"),
                godotTip = "Tip: Apply negative Y velocity to spark coordinates to trigger slow, floaty upward-drifting cross symbols."
            )
        )
    }

    val comboDetails = remember {
        listOf(
            ComboDetail("Fire Tornado", "🔥 Fire + 🌪️ Wind", "Searing plasma vortex pulling targets inward", Color(0xFFFF6D00)),
            ComboDetail("Electro Frost", "⚡ Electric + ❄️ Ice", "Shattering ice shards emitting high-voltage discharges", Color(0xFF00E5FF)),
            ComboDetail("Magma Spike", "🪨 Earth + 🔥 Fire", "Erupting molten rock pillars dealing explosive splash damage", Color(0xFFFFD600)),
            ComboDetail("Void Nova", "🔮 Void + 🟣 Gravity", "Collapsing black hole triggering gravity detonation waves", Color(0xFFD500F9))
        )
    }

    val impactVariations = remember {
        listOf(
            ImpactVariation("LIGHT", "Minor Sparks & Shards", "Low-density glows used for fast dual-daggers and light bullet hits.", Color(0xFF00E676)),
            ImpactVariation("MEDIUM", "Radial Blast Ring", "Focused shockwave with embers used for standard heavy sword swings.", Color(0xFFFFD600)),
            ImpactVariation("HEAVY", "High-Intensity Flares", "Wide thermal expanding sphere with shockwave, dealing high kinetic impact.", Color(0xFFFF6D00)),
            ImpactVariation("CRITICAL", "Dynamic Debris Burst", "Screen-shake inducing eruptive explosion with fractured rock blocks and neon fire.", Color(0xFFFF1744))
        )
    }

    Row(
        modifier = Modifier
            .fillMaxSize()
            .padding(2.dp),
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        // Left Column: Scrollable Reference image and interactive guide
        Column(
            modifier = Modifier
                .weight(1.2f)
                .fillMaxHeight()
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            // Title & Concept Card
            Card(
                colors = CardDefaults.cardColors(containerColor = Color(0xFF0F1420)),
                border = BorderStroke(0.5.dp, Color(0xFF1E3A5F).copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(8.dp)) {
                    Text(
                        text = "🎨 QUANTUM EFFECT VISUAL ENGINE REFERENCE",
                        color = Color(0xFF00E5FF),
                        fontSize = 8.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace
                    )
                    Spacer(modifier = Modifier.height(2.dp))
                    Text(
                        text = "Authentic retro HD-2D Sprite and GPUParticles2D composition sheet. Built to ensure visual hierarchy, performance guidelines, and mechanical satisfaction on mobile screens.",
                        color = Color(0xFF8A99AD),
                        fontSize = 7.5.sp,
                        lineHeight = 10.sp
                    )
                }
            }

            // Real visual asset image showcase
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(130.dp)
                    .clip(RoundedCornerShape(6.dp))
                    .border(1.dp, Color(0xFFD500F9).copy(alpha = 0.5f), RoundedCornerShape(6.dp))
                    .background(Color.Black)
            ) {
                Image(
                    painter = painterResource(id = com.example.R.drawable.img_combat_effects),
                    contentDescription = "Quantum Effect Combat Effects Sprite Reference Sheet",
                    modifier = Modifier.fillMaxSize(),
                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                )
                
                // Overlay Badge
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .background(Color.Black.copy(alpha = 0.75f), RoundedCornerShape(topStart = 6.dp))
                        .padding(horizontal = 6.dp, vertical = 3.dp)
                ) {
                    Text(
                        text = "🔍 SPRITE SHEET: 1024x768 PX",
                        color = Color(0xFFFFD600),
                        fontSize = 6.5.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace
                    )
                }
            }

            // Elemental Combo Examples Card
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.Black.copy(alpha = 0.4f)),
                border = BorderStroke(0.5.dp, Color(0xFF1E3A5F).copy(alpha = 0.3f))
            ) {
                Column(modifier = Modifier.padding(8.dp)) {
                    Text(
                        text = "💥 ELEMENTAL SYNERGY COMBOS",
                        color = Color(0xFFFFD600),
                        fontSize = 8.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    
                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        comboDetails.forEach { combo ->
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color(0xFF0F1420), RoundedCornerShape(4.dp))
                                    .border(0.5.dp, combo.color.copy(alpha = 0.3f), RoundedCornerShape(4.dp))
                                    .padding(5.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Text(text = combo.name.uppercase(), color = combo.color, fontSize = 7.5.sp, fontWeight = FontWeight.Bold)
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(text = "(${combo.recipe})", color = Color(0xFF8A99AD), fontSize = 6.5.sp)
                                    }
                                    Text(text = combo.effect, color = Color.White, fontSize = 7.sp)
                                }
                                Box(
                                    modifier = Modifier
                                        .background(combo.color.copy(alpha = 0.15f), RoundedCornerShape(2.dp))
                                        .padding(horizontal = 4.dp, vertical = 2.dp)
                                ) {
                                    Text(text = "COMBO", color = combo.color, fontSize = 6.sp, fontWeight = FontWeight.ExtraBold)
                                }
                            }
                        }
                    }
                }
            }
        }

        // Right Column: Tabbed list of categories & click actions to swap active particle system
        Column(
            modifier = Modifier
                .weight(1.3f)
                .fillMaxHeight()
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            // Category list selector
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.Black.copy(alpha = 0.4f)),
                border = BorderStroke(0.5.dp, Color(0xFF1E3A5F).copy(alpha = 0.3f))
            ) {
                Column(modifier = Modifier.padding(6.dp)) {
                    Text(
                        text = "📂 REFERENCE CLASS SELECTOR",
                        color = Color(0xFFD500F9),
                        fontSize = 8.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace
                    )
                    Spacer(modifier = Modifier.height(4.dp))

                    categoryDetails.forEachIndexed { idx, cat ->
                        val isSelected = selectedCategoryIndex == idx
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { selectedCategoryIndex = idx }
                                .background(
                                    if (isSelected) Color(0xFFD500F9).copy(alpha = 0.12f) else Color.Transparent,
                                    RoundedCornerShape(4.dp)
                                )
                                .border(
                                    0.5.dp,
                                    if (isSelected) Color(0xFFD500F9).copy(alpha = 0.6f) else Color.Transparent,
                                    RoundedCornerShape(4.dp)
                                )
                                .padding(6.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "${cat.emoji} ${cat.title.uppercase()}",
                                    color = if (isSelected) Color.White else Color(0xFF8A99AD),
                                    fontSize = 7.5.sp,
                                    fontWeight = FontWeight.Bold
                                )
                                if (isSelected) {
                                    Text(
                                        text = "ACTIVE",
                                        color = Color(0xFFD500F9),
                                        fontSize = 6.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        fontFamily = FontFamily.Monospace
                                    )
                                }
                            }
                            if (isSelected) {
                                Spacer(modifier = Modifier.height(3.dp))
                                Text(
                                    text = cat.description,
                                    color = Color.White,
                                    fontSize = 7.sp,
                                    lineHeight = 9.sp
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = cat.godotTip,
                                    color = Color(0xFF00E5FF),
                                    fontSize = 6.5.sp,
                                    fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                                    lineHeight = 9.sp
                                )
                                
                                Spacer(modifier = Modifier.height(4.dp))
                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    cat.combatVfxIds.forEach { vid ->
                                        val element = vfxElementsList.find { it.id == vid }
                                        if (element != null) {
                                            Box(
                                                modifier = Modifier
                                                    .background(Color(0xFF1E3A5F).copy(alpha = 0.5f), RoundedCornerShape(3.dp))
                                                    .border(0.5.dp, Color(0xFF00E5FF).copy(alpha = 0.5f), RoundedCornerShape(3.dp))
                                                    .clickable { onSelectVfx(element) }
                                                    .padding(horizontal = 4.dp, vertical = 2.dp)
                                            ) {
                                                Text(
                                                    text = "🖥️ SIMULATE ${element.name.split(" ").last()}",
                                                    color = Color(0xFF00E5FF),
                                                    fontSize = 6.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Impact variations card
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.Black.copy(alpha = 0.4f)),
                border = BorderStroke(0.5.dp, Color(0xFF1E3A5F).copy(alpha = 0.3f))
            ) {
                Column(modifier = Modifier.padding(6.dp)) {
                    Text(
                        text = "📊 IMPACT VARIATION DENSITY SPECS",
                        color = Color(0xFF00E5FF),
                        fontSize = 8.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace
                    )
                    Spacer(modifier = Modifier.height(4.dp))

                    impactVariations.forEach { iv ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFF0C1017), RoundedCornerShape(4.dp))
                                .padding(5.dp),
                            horizontalArrangement = Arrangement.spacedBy(6.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(14.dp)
                                    .background(iv.color.copy(alpha = 0.15f), CircleShape)
                                    .border(1.dp, iv.color, CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(text = iv.tier[0].toString(), color = iv.color, fontSize = 7.sp, fontWeight = FontWeight.Bold)
                            }

                            Column(modifier = Modifier.weight(1f)) {
                                Text(text = "${iv.tier} IMPACT: ${iv.title.uppercase()}", color = iv.color, fontSize = 7.sp, fontWeight = FontWeight.Bold)
                                Text(text = iv.desc, color = Color(0xFF8A99AD), fontSize = 6.5.sp, lineHeight = 8.sp)
                            }
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                    }
                }
            }
        }
    }
}

// Data structures for the VFX reference sheet
data class CategoryDetail(
    val title: String,
    val emoji: String,
    val description: String,
    val combatVfxIds: List<String>,
    val godotTip: String
)

data class ComboDetail(
    val name: String,
    val recipe: String,
    val effect: String,
    val color: Color
)

data class ImpactVariation(
    val tier: String,
    val title: String,
    val desc: String,
    val color: Color
)

@Composable
fun BoxScope.SkeletalNodeButton(
    slot: AugmentSlot,
    currentSelected: AugmentSlot,
    onSelect: () -> Unit,
    biasX: Float,
    biasY: Float
) {
    val alignment = BiasAlignment(biasX, biasY)
    val isSelected = slot == currentSelected

    Box(
        modifier = Modifier
            .align(alignment)
            .size(48.dp)
            .clickable(
                interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                indication = null,
                onClick = onSelect
            ),
        contentAlignment = Alignment.Center
    ) {
        Box(
            modifier = Modifier
                .size(14.dp)
                .background(
                    color = if (isSelected) QuantumNeonOrange else QuantumNeonBlue,
                    shape = CircleShape
                )
                .border(2.dp, Color.White, CircleShape)
        )
    }
}

fun getGdscriptCodeForSlot(slot: AugmentSlot): String {
    return when (slot) {
        AugmentSlot.CRANIAL -> """
# ==========================================
# CranialSynapseNode.gd - "Quantum Effect"
# Mobile Optimized Sub-second Tick Regulator
# ==========================================
extends Node

signal process_completed(duration_ms)

@export var is_overclocked: bool = true
var _total_ticks: int = 0

func _physics_process(delta: float) -> void:
    if is_overclocked:
        var start_time = Time.get_ticks_usec()
        _calculate_neural_matrices()
        var elapsed = (Time.get_ticks_usec() - start_time) / 1000.0
        if _total_ticks % 60 == 0:
            emit_signal("process_completed", elapsed)
    _total_ticks += 1

func _calculate_neural_matrices() -> void:
    var focus_mult = 1.35
    var vector_a = Vector2(100, 200)
    var vector_b = Vector2(300, 400)
    var dist = vector_a.distance_squared_to(vector_b) * focus_mult
""".trimIndent()

        AugmentSlot.SENSORY -> """
# ==========================================
# SensoryRadarScanner.gd - "Quantum Effect"
# Low-Cost Overlapping Concentric Area Scanner
# ==========================================
extends Area2D

signal threats_scanned(count)

@export var scan_radius: float = 120.0
var _scan_timer: float = 0.0
const SCAN_INTERVAL: float = 0.15

func _ready() -> void:
    get_node("CollisionShape2D").shape.radius = scan_radius

func _process(delta: float) -> void:
    _scan_timer += delta
    if _scan_timer >= SCAN_INTERVAL:
        _scan_timer = 0.0
        _perform_area_sweep()

func _perform_area_sweep() -> void:
    var overlapping_bodies = get_overlapping_bodies()
    var threat_count = 0
    for body in overlapping_bodies:
        if body.is_in_group("enemies"):
            threat_count += 1
    emit_signal("threats_scanned", threat_count)
""".trimIndent()

        AugmentSlot.TORSO -> """
# ==========================================
# TorsoDeflectorChassis.gd - "Quantum Effect"
# Dynamic Kinetic Deflection & Damage Multipliers
# ==========================================
extends CollisionShape2D

signal damage_absorbed(amount)

@export var base_deflection_rate: float = 0.25
@export var charge_regeneration: float = 5.0

var shield_charge: float = 100.0
var max_shield: float = 100.0

func process_kinetic_impact(incoming_dmg: float) -> float:
    var absorbed = incoming_dmg * base_deflection_rate
    shield_charge = clampf(shield_charge - absorbed * 0.5, 0.0, max_shield)
    emit_signal("damage_absorbed", absorbed)
    return incoming_dmg - absorbed
""".trimIndent()

        AugmentSlot.QUANTUM_CORE -> """
# ==========================================
# QuantumReactorCore.gd - "Quantum Effect"
# Particle System Energy Draw and MP Capacitors
# ==========================================
extends GPUParticles2D

signal core_resonance_reached(frequency)

@export var draw_rate: float = 2.5
var active_resonance: float = 440.0

func trigger_energy_draw(mp_consumed: float) -> void:
    self.amount = int(clampf(mp_consumed * 5.0, 10.0, 150.0))
    self.emitting = true
    
    var t = create_tween()
    t.tween_property(self, "speed_scale", 2.2, 0.4)
    t.tween_property(self, "speed_scale", 1.0, 0.8)
    emit_signal("core_resonance_reached", active_resonance + mp_consumed)
""".trimIndent()

        AugmentSlot.ARMS -> """
# ==========================================
# ArmActuatorStabilizer.gd - "Quantum Effect"
# Aiming Interpolation & Dynamic Recoil Lerp
# ==========================================
extends Node2D

@export var sway_reduction: float = 0.45
@export var lerp_weight: float = 0.15

var _target_aim_angle: float = 0.0
var _current_aim_angle: float = 0.0

func update_actuator_aim(target_pos: Vector2) -> void:
    _target_aim_angle = (target_pos - global_position).angle()
    _current_aim_angle = lerp_angle(_current_aim_angle, _target_aim_angle, lerp_weight)
    global_rotation = _current_aim_angle
""".trimIndent()

        AugmentSlot.LEGS -> """
# ==========================================
# LegBoosterPhysics.gd - "Quantum Effect"
# Isometric Slide Friction Calculations
# ==========================================
extends CharacterBody2D

@export var slide_friction: float = 0.88
@export var dash_speed_mult: float = 2.5

var is_sliding: bool = false
var slide_vector: Vector2 = Vector2.ZERO

func apply_mobility_thrust(move_input: Vector2, speed: float) -> void:
    if is_sliding:
        slide_vector = slide_vector * slide_friction
        velocity = slide_vector
        if velocity.length_squared() < 100.0:
            is_sliding = false
    else:
        velocity = move_input * speed
    move_and_slide()
""".trimIndent()

        AugmentSlot.DERMAL -> """
# ==========================================
# AdaptiveDermalShield.gd - "Quantum Effect"
# Environment Hazard Filter Line Controller
# ==========================================
extends Line2D

@export var thermal_resistance: float = 0.35
var _opacity_phase: float = 0.0

func _process(delta: float) -> void:
    _opacity_phase += delta * 4.0
    var alpha = 0.4 + sin(_opacity_phase) * 0.2
    self.default_color.a = alpha
""".trimIndent()
    }
}

fun getKotlinCodeForSlot(slot: AugmentSlot): String {
    return when (slot) {
        AugmentSlot.CRANIAL -> """
// Synaptic Synapse Controller Equivalent in Jetpack Compose
@Composable
fun SynapticCranialOverclocker(
    synapticTicksFlow: StateFlow<Long>,
    modifier: Modifier = Modifier
) {
    val tickCount by synapticTicksFlow.collectAsState()
    val glowBrush = remember {
        Brush.radialGradient(listOf(Color(0xFF00E5FF), Color.Transparent))
    }
    Box(modifier = modifier.size(64.dp)) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            val radius = size.minDimension / 2f
            drawCircle(brush = glowBrush, radius = radius * (1.0f + sin(tickCount * 0.1f) * 0.15f))
        }
    }
}
""".trimIndent()

        AugmentSlot.SENSORY -> """
// Concentric Overlapping Scanner Equivalent in Jetpack Compose
@Composable
fun ConcentricSensoryArray(
    scanResultFlow: StateFlow<Int>,
    modifier: Modifier = Modifier
) {
    val activeThreats by scanResultFlow.collectAsState()
    val sweepPulse = rememberInfiniteTransition().animateFloat(
        initialValue = 0f, targetValue = 1f,
